const DATE_CACHE = new Map(); // "2026-10-05" → "Oct 5, 2026" (bounded)

class AppView {
  constructor(root) { this.root = root; }
  applyDisplay(model) {
    const systemDark = typeof matchMedia === "function" && matchMedia("(prefers-color-scheme: dark)").matches;
    document.documentElement.dataset.theme = model.settings.theme === "system" ? (systemDark ? "dark" : "light") : model.settings.theme;
    document.documentElement.dataset.icons=model.settings.showIcons?"on":"off";
    document.documentElement.dataset.fontSize = model.settings.fontSize;
    document.documentElement.dataset.contrast = model.settings.highContrast ? "high" : "normal";
    // Animations are on by default; only the device's own "reduce motion" accessibility setting turns them off.
    document.documentElement.dataset.motion = "system";
    document.documentElement.dataset.stickyColumn = model.settings.stickyFirstColumn ? "on" : "off";
    document.documentElement.style.setProperty("--accent", model.settings.accentColor);
    document.documentElement.style.setProperty("--focus", model.settings.accentColor);
  }
  render(model) {
    this.model=model; this.applyDisplay(model);
    document.documentElement.dataset.density = model.settings.density;
    // The full layout always renders. A new shared server starts with no workspaces (local mode always has at least
    // one): the sidebar and main area then show the "create your first workspace" state (see noWorkspaces).
    this.root.innerHTML = `<div class="app-shell">${this.sidebar(model)}<div class="nav-backdrop" aria-hidden="true"></div><main class="workspace">${this.topbar(model)}${this.content(model)}</main></div><input id="import-file" class="sr-only" type="file" accept="application/json,.json,text/csv,.csv" data-action="import-file"><input id="avatar-file" class="sr-only" type="file" accept="image/png,image/jpeg,image/webp" data-action="avatar-file"><div id="overlay-root"></div>`;
    this.afterRender(model);
  }

  // Microsoft Entra ID sign-in page (resource mode with AUTH_MODE=entra). No password field: Microsoft handles sign-in.
  renderEntraGate(state, model, { busy = false, signingOut = false, message = "" } = {}) {
    if (model) this.applyDisplay(model);
    const screens = {
      "signed-out": ["Sign in to JARC Database", "Use your Microsoft 365 work account to open your workspaces.", "entra-sign-in", "Sign in with Microsoft"],
      expired: ["Your session has expired", "For your security you've been signed out. Sign in again to continue — changes that weren't saved need to be made again.", "entra-sign-in", "Sign in again"],
      denied: ["You don't have access", "Your Microsoft account isn't allowed to use JARC Database, or your JARC account is disabled. Contact a JARC administrator, or use a different account.", "entra-sign-out", "Use a different account"],
      error: ["Microsoft sign-in isn't available", message || "Try again in a moment.", "entra-sign-in", "Try again"]
    };
    const [title, text, action, label] = screens[state] || screens["signed-out"];
    const logo = `<svg class="entra-ms-logo" viewBox="0 0 21 21" aria-hidden="true" focusable="false"><rect x="1" y="1" width="9" height="9" fill="#f25022"/><rect x="11" y="1" width="9" height="9" fill="#7fba00"/><rect x="1" y="11" width="9" height="9" fill="#00a4ef"/><rect x="11" y="11" width="9" height="9" fill="#ffb900"/></svg>`;
    const working = signingOut ? "Signing you out…" : "Redirecting to Microsoft…";
    this.root.innerHTML = `<main class="entra-login" data-state="${this.attr(state)}"><section class="entra-card" aria-labelledby="entra-title"><div class="entra-brand"><span class="entra-mark" aria-hidden="true">J</span><span>JARC Database</span></div><h1 id="entra-title">${this.escape(title)}</h1><p class="entra-text">${this.escape(text)}</p><div class="entra-status" role="status" aria-live="polite">${busy ? `<span class="entra-spinner" aria-hidden="true"></span>${this.escape(working)}` : ""}</div><button type="button" class="entra-button" data-action="${this.attr(action)}" ${busy ? "disabled aria-busy=\"true\"" : ""}>${action === "entra-sign-in" ? logo : ""}<span>${this.escape(label)}</span></button><p class="entra-note">Secured by Microsoft Entra ID. JARC never sees or stores your password.</p></section></main><div id="overlay-root"></div>`;
  }

  renderLogin(auth, model) {
    this.applyDisplay(model);
    const username=auth.draftUsername??auth.rememberedUsername;
    this.root.innerHTML=`<main class="login-shell login-redesign"><header class="login-top"><a class="login-wordmark" href="#login-form" aria-label="JARC — jump to sign in"><span class="brand-mark">J</span><span><strong>JARC</strong><small>Operations Database</small></span></a><div class="login-theme" role="group" aria-label="Sign-in appearance">${[["light","sun"],["dark","moon"],["system","monitor"]].map(([t,ic])=>`<button type="button" data-action="login-theme-choice" data-theme="${t}" aria-label="${this.cap(t)} theme" aria-pressed="${model.settings.theme===t}" title="${this.cap(t)} theme">${icon(ic)}</button>`).join("")}</div></header>
      <div class="login-stage"><section class="login-story" aria-labelledby="login-story-title"><div class="login-story-copy"><span class="login-kicker"><i></i> Operations, in sync</span><h1 id="login-story-title">Your work.<br><span>Connected.</span></h1><p>Bring every record, board and next step<br>into one beautifully organized workspace.</p></div><div class="login-art" aria-hidden="true"><div class="art-coordinate-grid"></div><div class="art-halo"></div><div class="art-ring ring-one"></div><div class="art-ring ring-two"></div><div class="art-ring ring-three"></div><div class="art-core"><span>J</span><i></i></div><div class="art-node node-one">${icon("board")}</div><div class="art-node node-two">${icon("records")}</div><div class="art-node node-three">${icon("work")}</div><span class="art-dot dot-one"></span><span class="art-dot dot-two"></span></div><div class="login-story-footer"><span class="story-rule"></span><span>One place for every moving part.</span></div></section>
      <section class="login-panel" aria-labelledby="signin-title"><div class="login-form-wrap"><div class="login-form-eyebrow"><span></span> Your workspace awaits</div><div class="login-form-heading"><h2 id="signin-title">Welcome back.</h2><p>${auth.lockedScreen?"Unlock your workspace to pick up where you left off.":"A little focus. A lot of possibilities. Sign in to continue."}</p></div><form id="login-form" class="login-form" data-action="login-form">${auth.error?`<div id="login-error" class="login-error" role="alert">${icon("lock")}<span>${this.escape(auth.error)}</span></div>`:""}<div class="login-field"><label for="login-username">Username</label><input id="login-username" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required value="${this.escape(username)}" placeholder="Your username" ${username?"":"autofocus"} ${auth.error?'aria-describedby="login-error"':""}></div><div class="login-field"><label for="login-password">Password</label><div class="password-field"><input id="login-password" name="password" type="password" autocomplete="current-password" required placeholder="Your password" data-action="password-input" aria-describedby="caps-warning${auth.error?" login-error":""}" ${username?"autofocus":""}><button type="button" data-action="toggle-password" aria-label="Show password" aria-controls="login-password" aria-pressed="false">Show</button></div><small id="caps-warning" class="caps-warning" role="status" hidden>Caps Lock is on.</small></div><div class="login-options"><label><input type="checkbox" name="rememberUsername" ${(auth.draftRememberUsername??Boolean(auth.rememberedUsername))?"checked":""}><span>Remember my username</span></label><label><input type="checkbox" name="rememberSession" ${auth.draftRememberSession?"checked":""}><span>Keep me signed in <small>Use only on your personal device.</small></span></label></div><button class="button primary login-submit" type="submit" ${auth.lockSeconds?"disabled":""}><span>${auth.lockSeconds?"Try again in "+auth.lockSeconds+"s":auth.lockedScreen?"Unlock workspace":"Sign in"}</span>${icon("right")}</button><details class="login-help"><summary>Need help signing in?</summary><p>Use the username and password provided for this workspace. Check Caps Lock or use Show to check your password. If you don't know your credentials, contact the person who set up JARC.</p></details></form><div class="login-local-note">${icon("records")}<span>Your work is saved in this browser.<br><strong>Use this device to continue where you left off.</strong></span></div></div></section></div><footer class="login-bottom"><span>JARC / Operations Database</span><span>Your workspace. Your momentum.</span></footer></main>`;
    requestAnimationFrame(()=>this.root.querySelector('[autofocus]')?.focus());
  }

  sidebar(model) {
    return `<aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">J</span><div class="brand-copy"><strong>Jarc</strong><small>Operations Database</small></div><button class="sidebar-collapse-top" data-action="collapse-nav" aria-label="Collapse sidebar" title="Collapse sidebar">${icon("chevron")}</button></div><nav aria-label="Primary navigation">
      <button class="nav-item ${model.screen === "home" ? "active" : ""}" data-action="nav" data-screen="home" data-tooltip="Home">${icon("home")}<span class="nav-text">Home</span></button>
      <button class="nav-item ${model.screen === "mywork" ? "active" : ""}" data-action="nav" data-screen="mywork" data-tooltip="My work">${icon("work")}<span class="nav-text">My work</span><span class="nav-count">${model.myWork.length}</span></button>
      <button class="nav-item ${model.screen === "integrations" ? "active" : ""}" data-action="nav" data-screen="integrations" data-tooltip="Integrations">${icon("link")}<span class="nav-text">Integrations</span></button>
      <button class="nav-item" data-action="command-palette" data-tooltip="Search">${icon("search")}<span class="nav-text">Search</span><span class="nav-shortcut">Ctrl K</span></button>
      <div class="workspace-heading"><p class="nav-label">Workspaces</p><button class="mini-button" data-action="create-workspace" aria-label="Create workspace" title="Create workspace">${icon("plus")}</button></div>
      ${model.workspace?`<button class="workspace-switch" data-action="workspace-menu" data-tooltip="${this.escape(model.workspace.name)}"><span class="workspace-icon" style="background:${this.cssColor(model.workspace.color)}">${this.escape(model.workspace.name[0]||"")}</span><span class="workspace-name"><strong>${this.escape(model.workspace.name)}</strong><small>${model.workspace.boards.length} boards</small></span>${icon("chevron")}</button><button class="workspace-collapse" data-action="toggle-workspace-section" aria-label="Collapse workspace boards" title="Collapse workspace boards">${icon("chevron")}</button>
      ${model.favoriteBoards.length?`<div class="favorite-nav"><p class="nav-label">Favorites</p>${model.favoriteBoards.map(b=>`<button class="tree-item" data-action="open-record-board" data-board="${this.attr(b.id)}" data-workspace="${this.attr(b.workspaceId)}" title="${this.escape(b.name)}">${icon("star")}<span class="nav-text">${this.escape(b.name)}</span></button>`).join("")}</div>`:""}<div class="nav-tree">${model.workspace.boards.filter(b=>!b.archived).map((board) => `<div data-board-context="${this.attr(board.id)}" class="board-nav ${model.screen === "board" && model.currentBoardId === board.id ? "selected" : ""}"><button class="tree-item" data-action="open-board" data-id="${this.attr(board.id)}" data-tooltip="${this.escape(board.name)}"><span class="tree-icon">${icon("board")}</span><span class="nav-text">${this.escape(board.name)}</span>${model.settings.showBoardCounts?`<small class="nav-count">${model.boardRecordCount(board)}</small>`:""}</button><button class="board-menu-button" data-action="board-menu" data-id="${this.attr(board.id)}" aria-label="Board options" title="Board options">${icon("more")}</button></div>`).join("")}<button class="new-board-nav" data-action="new-board">${icon("plus")} <span class="nav-text">New board</span></button></div>`:`<div class="nav-empty-workspaces"><p class="nav-text">No workspaces yet</p><button class="new-board-nav" data-action="create-workspace" data-tooltip="Create workspace">${icon("plus")} <span class="nav-text">Create workspace</span></button></div>`}
    </nav><div class="sidebar-footer"><button class="sidebar-settings" data-action="settings" title="Settings">${icon("settings")}<span>Settings</span></button><button class="sidebar-settings" data-action="shortcuts" title="Keyboard shortcuts (?)">${icon("command")}<span>Keyboard shortcuts</span></button></div></aside>`;
  }

  topbar(model) {
    const avatar=this.safeImage(model.profile.avatar)?`<img src="${this.attr(this.safeImage(model.profile.avatar))}" alt="">`:this.escape(model.profile.initials);
    return `<header class="topbar"><div class="top-context"><button class="icon-button mobile-only nav-toggle" data-action="toggle-nav" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false"><span class="nav-toggle-open">${icon("menu")}</span><span class="nav-toggle-close">${icon("close")}</span></button><span>${this.escape(model.workspace?.name||"JARC Database")}</span><span class="context-divider">/</span><strong>${!model.workspace?"Get started":model.screen==="home"?"Home":model.screen==="mywork"?"My work":this.escape(model.board?.name||"Boards")}</strong></div><button class="global-search-button" data-action="command-palette">${icon("search")}<span>Search JARC</span><kbd>Ctrl K</kbd></button><div class="top-actions"><button class="save-state" data-action="retry-save" title="Data is saved in this browser" aria-live="polite"><i></i> Saved locally</button><button class="notification-button icon-button" data-action="notifications" aria-label="Notifications">${icon("bell")}${model.unreadCount?`<b>${model.unreadCount}</b>`:""}</button><button class="profile profile-button" data-action="profile-menu" style="background:${this.cssColor(model.profile.color,"#0f9489")}" aria-label="Open profile">${avatar}</button></div></header>`;
  }

  content(model) {
    if (model.screen === "integrations" && this.integrations) return this.integrations.html();
    if (!model.workspace) return this.noWorkspaces(model);
    if (model.screen === "home") return this.home(model);
    if (model.screen === "mywork") return this.myWork(model);
    return model.board?this.boardScreen(model):this.home(model);
  }

  home(model) {
    const boards=model.workspace.boards.filter(b=>Boolean(b.archived)===Boolean(model.settings.homeArchived));
    const rows=model.allRecords.filter(r=>r.workspaceId===model.workspace.id&&!r.archived&&!r.boardArchived);
    const mine=model.myWork.filter(r=>r.workspaceId===model.workspace.id), due=rows.filter(r=>model.isDueSoon(r));
    const sort=model.settings.homeSort||"updated";
    boards.sort((a,b)=>sort==="name"?a.name.localeCompare(b.name):sort==="used"?(b.openCount||0)-(a.openCount||0):String(b[sort==="created"?"createdAt":"updatedAt"]||b.activity?.[0]?.at||"").localeCompare(String(a[sort==="created"?"createdAt":"updatedAt"]||a.activity?.[0]?.at||"")));
    const recent=model.recentBoardItems.slice(0,3);
    const recordLink=r=>`<button class="focus-record" data-action="palette-record" data-id="${this.attr(r.id)}" data-board="${this.attr(r.boardId)}" data-workspace="${this.attr(r.workspaceId)}"><span class="record-avatar">${icon("records")}</span><span><strong>${this.escape(r.serial)}</strong><small>${this.escape(r.boardName)}</small></span><span class="meta">${r.dueDate?this.date(r.dueDate):this.escape(r.status||"")}</span>${icon("chevron")}</button>`;
    return `<div class="home-content"><section class="page-head"><div><div class="eyebrow">${this.escape(model.workspace.name)}</div><h1>Welcome back, ${this.escape(model.profile.name.split(" ")[0])}</h1><p>Pick up where you left off, or make room for what's next.</p></div><button class="button primary" data-action="new-board">${icon("plus")} New board</button></section>
    <div class="home-command-row"><button class="home-command" data-action="command-palette">${icon("search")}<span>Search or jump to…</span><kbd>Ctrl K</kbd></button><button class="button secondary" data-action="home-create-record" ${model.workspace.boards.some(b=>!b.archived)?"":"disabled"}>${icon("plus")} New record</button><button class="button secondary" data-action="home-import" ${model.workspace.boards.some(b=>!b.archived)?"":"disabled"}>${icon("import")} Import data</button></div>
    <section class="workspace-summary">${[["Boards",model.workspace.boards.filter(b=>!b.archived).length,"board"],["Records",rows.length,"records"],["Assigned to me",mine.length,"people"],["Due in 7 days",due.length,"calendar"]].map(([label,n,ic])=>`<div><span>${icon(ic)} ${label}</span><strong>${n}</strong></div>`).join("")}</section>
    ${!model.settings.dismissedHint?`<div class="onboarding-hint">${icon("command")}<span>Your next action is a keystroke away. <strong>Ctrl K</strong> finds boards, records and commands.</span><button class="icon-button" data-action="dismiss-hint" aria-label="Dismiss keyboard tip">${icon("close")}</button></div>`:""}
    ${recent.length?`<section class="continue-section"><div class="section-heading"><h2>Continue working</h2><span>Recently opened</span></div><div class="continue-grid">${recent.map(b=>`<article class="continue-card"><button class="continue-open" data-action="open-record-board" data-board="${this.attr(b.id)}" data-workspace="${this.attr(b.workspaceId)}"><span class="board-tile-icon">${icon("board")}</span><small>${this.escape(b.workspaceName)}</small><strong>${this.escape(b.name)}</strong><span>${model.boardRecordCount(b)} records <span class="dot-separator">·</span> ${b.updatedAt?"Updated "+this.relative(b.updatedAt):"Opened "+this.relative(b.openedAt)}</span></button><button class="card-menu icon-button" data-action="board-menu" data-id="${this.attr(b.id)}" data-workspace="${this.attr(b.workspaceId)}" aria-label="Actions for ${this.escape(b.name)}">${icon("more")}</button></article>`).join("")}</div></section>`:""}
    <section class="focus-grid"><div class="focus-panel"><div class="section-heading"><h2>Assigned to me <small>${mine.length}</small></h2><button data-action="nav" data-screen="mywork">View all</button></div>${mine.slice(0,3).map(recordLink).join("")||`<div class="quiet-empty">${icon("work")}<span><strong>You're clear for now</strong><small>Records assigned to you will appear here.</small></span></div>`}</div><div class="focus-panel"><div class="section-heading"><h2>Due soon <small>${due.length}</small></h2></div>${due.slice(0,3).map(recordLink).join("")||`<div class="quiet-empty">${icon("calendar")}<span><strong>No upcoming deadlines</strong><small>Due dates in the next 7 days appear here.</small></span></div>`}</div></section>
    <section class="boards-section"><div class="section-heading"><h2>Your boards <small>${boards.length}</small></h2><div class="section-controls"><button data-action="toggle-home-archived" class="${model.settings.homeArchived?"active":""}">${model.settings.homeArchived?"Show active":"Archived"}</button><label class="sr-only" for="home-sort">Sort boards</label><select id="home-sort" data-action="home-sort">${[["updated","Recently updated"],["name","Name"],["created","Created"],["used","Most used"]].map(([v,t])=>`<option value="${v}" ${sort===v?"selected":""}>${t}</option>`).join("")}</select></div></div><div class="board-list">${boards.map(b=>`<article class="board-list-row" data-board-context="${this.attr(b.id)}" data-workspace="${this.attr(model.workspace.id)}"><button class="board-list-open" data-action="open-board" data-id="${this.attr(b.id)}"><span class="board-tile-icon">${icon("board")}</span><span><strong>${this.escape(b.name)}</strong><small>${this.escape(b.description||model.workspace.name)}</small></span><span class="board-stat">${model.boardRecordCount(b)} records</span><span class="board-stat">${b.activity.length} updates</span><span class="board-age">${b.updatedAt?this.relative(b.updatedAt):"No recent activity"}</span></button><button class="icon-button favorite-control ${b.favorite?"active":""}" data-action="favorite-board" data-id="${this.attr(b.id)}" aria-label="${b.favorite?"Unpin":"Pin"} ${this.escape(b.name)}">${icon("star")}</button><button class="icon-button" data-action="board-menu" data-id="${this.attr(b.id)}" aria-label="Actions for ${this.escape(b.name)}">${icon("more")}</button></article>`).join("")||`<div class="empty-state"><span class="empty-symbol">${icon("board")}</span><h2>${model.settings.homeArchived?"No archived boards":"No boards yet"}</h2><p>Create a board to start organizing your work.</p><button class="button primary" data-action="new-board">${icon("plus")} Create board</button></div>`}</div></section></div>`;
  }


  // No workspaces yet (a new shared database): an invitation to create the first one, inside the normal layout.
  noWorkspaces(model) {
    const shared=model.storage?.adapter?.mode==="resource";
    const steps=[["layout","Create a workspace","One per team, site or project."],["board","Add boards","Tables for jobs, assets, orders or anything you track."],["records","Fill in records","Edit cells in place, import CSV files and assign owners."]];
    return `<section class="no-workspace" aria-labelledby="no-workspace-title"><div class="no-workspace-card"><span class="empty-symbol">${icon("layout")}</span><div class="eyebrow">Welcome${model.profile?.name?", "+this.escape(String(model.profile.name).split(" ")[0]):""}</div><h1 id="no-workspace-title">Create your first workspace</h1><p>${shared?"There are no workspaces in JARC Database yet. Workspaces you create are saved to the shared database.":"There are no workspaces yet. Create one to start organizing boards and records."}</p><button class="button primary no-workspace-create" data-action="create-workspace">${icon("plus")} Create workspace</button><ol class="no-workspace-steps">${steps.map(([ic,title,text])=>`<li><span class="no-workspace-step-icon">${icon(ic)}</span><span><strong>${title}</strong><small>${text}</small></span></li>`).join("")}</ol></div></section>`;
  }

  myWork(model) {
    const rows = model.myWork;
    return `<section class="page-head"><div><div class="eyebrow">Assigned to ${this.escape(model.profile.initials)}</div><h1>My work</h1><p>Items assigned to you across every workspace and board.</p></div></section><section class="data-region"><div class="group-title"><span class="status-dot landing"></span>Assigned items <small>${rows.length}</small></div>${rows.length ? this.crossBoardTable(rows) : this.blank("work", "Nothing assigned yet", `Choose ${this.escape(model.profile.initials)} as the owner of a record and it will appear here.`)}</section>`;
  }

  boardScreen(model) {
    return `<section class="board-head"><div class="board-breadcrumb mobile-only"><button data-action="nav" data-screen="home">${this.escape(model.workspace.name)}</button> / ${this.escape(model.board.name)}</div><div class="title-row"><div><h1><input class="board-title-input" data-action="board-title-inline" value="${this.escape(model.board.name)}" aria-label="Board name"></h1><button class="board-description ${model.board.description?"":"is-empty"}" data-action="edit-description" title="Edit description">${this.escape(model.board.description || "Add a clear description for this board")}</button></div><div class="board-actions"><button class="icon-button ${model.board.favorite ? "active" : ""}" data-action="toggle-favorite" aria-label="Favorite board" title="Favorite">${icon("star")}</button><button class="button secondary header-action" data-action="import" title="Import records from a CSV file or a JARC backup">${icon("import")} Import</button><button class="button secondary header-action" data-action="export" title="Export this board's records as CSV" ${model.rows.length ? "" : "disabled"}>${icon("export")} Export</button><button class="button primary" data-action="open-form">${icon("plus")} New record</button><button class="icon-button" data-action="board-menu" data-current="1" data-id="${this.attr(model.board.id)}" title="More board actions" aria-label="More board actions" aria-haspopup="menu">${icon("more")}</button></div></div>${this.tabs(model)}</section>${model.board.source?.readOnly ? `<div class="readonly-banner" role="note">${icon("lock")}<span><strong>Synced from monday.com.</strong> This board is read-only in JARC: changes arrive from monday.com.</span></div>` : ""}${this.toolbar(model)}${this.filterChips(model)}${model.selected.size ? this.bulkBar(model) : ""}<div class="board-view-region">${this.boardView(model)}</div>`;
  }

  // Views bar: Main Table, then the board's views as compact tabs, then "+ Views". Archived records open from the
  // board's More menu (or + Views) and show here as a closable tab.
  tabs(model) {
    const views=model.board.savedViews||[], active=model.activeView, icons=Object.fromEntries(VIEW_TYPES.map(([t,,i])=>[t,i])), main=!active&&!model.showArchived;
    return `<div class="view-tabs" role="tablist" aria-label="Board views"><span class="view-tab ${main?"active":""}"><button role="tab" aria-selected="${main}" data-action="main-table">${icon("layout")} Main Table</button></span>${views.map((v)=>{const on=!model.showArchived&&active&&String(active.id)===String(v.id);return `<span class="view-tab ${on?"active":""}"><button role="tab" aria-selected="${Boolean(on)}" data-action="open-view" data-id="${this.attr(v.id)}">${icon(icons[v.view]||"layout")} ${this.escape(v.name)}</button>${on?`<button class="view-tab-menu" data-action="view-menu" data-id="${this.attr(v.id)}" aria-label="Options for the ${this.attr(v.name)} view" aria-haspopup="menu" title="View options">${icon("chevron")}</button>`:""}</span>`;}).join("")}${model.showArchived?`<span class="view-tab active archived-tab"><button role="tab" aria-selected="true">${icon("archive")} Archived records <small>${model.archivedCount}</small></button><button class="view-tab-menu" data-action="main-table" aria-label="Close archived records" title="Back to Main Table">${icon("close")}</button></span>`:""}<button class="add-view-button" data-action="views-menu" aria-haspopup="menu">${icon("plus")} Views</button>${model.viewChanged?`<button class="view-save-button" data-action="save-active-view" title="Save this view's columns, filters and sorting">Save to this view</button>`:""}</div>`;
  }

  // Board toolbar: New record (with a menu for New group), search, person, status and quick filters, sort, columns,
  // Group by, more. Choices use themed menus (BoardGroups.js), not native selects, so they match light and dark mode.
  toolbar(model) {
    const editable=!model.board.source?.readOnly, hidden=model.board.columns.filter((c)=>!model.columnShown(c)).length;
    const quick={all:"All records",mine:"My records",due:"Due soon",recent:"Recently updated"}[model.quickFilter]||"All records";
    const newButton=editable?`<div class="split-button"><button class="button primary compact-primary" data-action="open-form">${icon("plus")} New record</button><button class="button primary split-toggle" data-action="toolbar-menu" data-menu="new" aria-haspopup="menu" aria-expanded="false" aria-label="More ways to create" title="New record or group">${icon("chevron")}</button></div>`:"";
    const person=model.ownerColumn?this.toolbarMenuButton("person",model.personFilter?this.escape(model.personLabel(model.personFilter)):"Person",{active:Boolean(model.personFilter),iconName:"user",title:"Show one person's records"}):"";
    const status=model.statusColumn?this.toolbarMenuButton("status",model.status==="All"?this.escape(model.statusColumn.label):this.escape(model.status),{active:model.status!=="All",iconName:"filter",title:`Filter by ${model.statusColumn.label}`}):"";
    const groupBy=this.toolbarMenuButton("groupby",model.groupByColumn?`Group: ${this.escape(model.groupByColumn.label)}`:"Group by",{active:Boolean(model.groupByColumn),iconName:"group",title:"Group this view by a column"});
    return `<section class="board-tools"><div class="tool-left">${newButton}<label class="search-field">${icon("search")}<input id="board-search" data-action="search" value="${this.escape(model.query)}" placeholder="Search this board" aria-label="Search records in this board"><kbd>/</kbd></label>${person}${status}${this.toolbarMenuButton("quick",quick,{active:model.quickFilter!=="all",title:"Quick filter"})}<button class="tool-button" data-action="sort">${icon("sort")} Sort</button><button class="tool-button ${hidden?"active":""}" data-action="column-picker" aria-haspopup="dialog" title="Choose which columns this view shows">${icon("hide")} Columns${hidden?` <small class="tool-count">${hidden} hidden</small>`:""}</button>${groupBy}</div><div class="tool-right"><button class="icon-button" data-action="view-overflow" title="More view options" aria-label="More view options">${icon("more")}</button></div></section>`;
  }


  // Floating bulk-action bar: count, then the actions that fit this board. Archive (restorable) and Delete (permanent)
  // are separate; Delete is last and red.
  bulkBar(model) {
    const n=model.selected.size, btn=(action,ic,label,extra="")=>`<button type="button" class="bulk-action ${extra}" data-action="${action}">${icon(ic)}<span>${label}</span></button>`;
    return `<div class="bulk-bar" role="toolbar" aria-label="${n} record${n===1?"":"s"} selected"><span class="bulk-count">${n}</span><strong class="bulk-label">${n===1?"Record":"Records"} selected</strong><div class="bulk-actions">${model.statusColumn?btn("bulk-status","tag","Status"):""}${model.priorityColumn?btn("bulk-priority","flag","Priority"):""}${model.ownerColumn?btn("bulk-owner","user","Assign"):""}${btn("bulk-duplicate","copy","Duplicate")}${btn("bulk-export","export","Export")}${model.showArchived?btn("bulk-restore","archive","Restore"):btn("bulk-archive","archive","Archive")}${model.board.groups.length>1?btn("group-pick","group","Group"):""}${btn("bulk-move","right","Move to")}${btn("delete-selected","trash","Delete","danger")}</div><button type="button" class="icon-button bulk-close" data-action="clear-selection" aria-label="Clear selection" title="Clear selection (Esc)">${icon("close")}</button></div>`;
  }
  // Resource mode loads a board's records when it opens: loading, failed and partly loaded (large board) states.
  boardView(model) {
    const load=model.boardLoadState();
    if(load.state==="loading"||load.state==="none")return this.boardSkeleton(model);
    if(load.state==="error")return `<section class="empty-state" role="alert"><span class="empty-symbol">${icon("records")}</span><h2>Records couldn't load</h2><p>${this.escape(model.boardLoadError||"Try again in a moment.")}</p><button class="button secondary" data-action="retry-board-load">Try again</button></section>`;
    const partial=load.state==="partial"?`<div class="notice partial-notice" role="status"><span>Showing the first ${Number(load.loaded||0).toLocaleString()} of ${Number(load.total||0).toLocaleString()} records. Search, filters and sorting apply to the loaded records.</span> <button class="button secondary" data-action="load-more-records">Load more</button></div>`:"";
    return partial+this.boardRecordsView(model);
  }
  boardRecordsView(model) {
    const rows=model.visibleRows; if(!rows.length&&(model.query||model.status!=="All"||model.quickFilter!=="all"||model.columnFilter))return `<section class="empty-state"><span class="empty-symbol">${icon("search")}</span><h2>No records match this view</h2><p>Try a different search or remove the active filters.</p><button class="button secondary" data-action="clear-filters">Clear search and filters</button></section>`; if(!rows.length&&(model.showArchived||model.currentView!=="table"))return this.blank("records",model.showArchived?"No archived records":"No records yet",model.showArchived?"Archived records will appear here.":"Create a record or import data to get started.",!model.showArchived);
    // The table view keeps its header and add actions even with zero records, on every screen size.
    if(model.currentView==="list") return this.listView(rows,model);
    if(model.currentView==="kanban") return this.kanbanView(rows,model);
    if(model.currentView==="calendar") return this.calendarView(rows,model);
    // Table: Group by (a column, presentation only) or the board's own groups; archived records list flat.
    if(model.groupByColumn&&!model.showArchived)return this.columnGroupsView(rows,model);
    if(model.board.groups.length&&!model.showArchived)return this.boardGroupsView(rows,model);
    if(model.grouped&&model.groupColumn){return `<section class="data-region grouped-region">${[...new Set([...model.board.groups,...rows.map(r=>r[model.groupColumn.key]||"Ungrouped")])].map(g=>{const gr=rows.filter(r=>(r[model.groupColumn.key]||"Ungrouped")===g);return `<div class="group-block"><div class="group-title"><span class="group-marker"></span>${this.escape(g)} <small>${gr.length}</small></div>${this.table(gr,model,g==="Ungrouped"?"":g)}</div>`}).join("")}</section>`;}
    return `<section class="data-region"><div class="group-title"><span class="group-marker group-new"></span>All records <small>${rows.length}</small></div>${this.table(rows,model)}</section>`;
  }
  // Resolve a record's display fields through the board's columns, never fixed keys.
  fieldKeys(model){const cols=model.board.columns,dates=cols.filter(c=>c.type==="date");const due=model.dueColumn();return {status:model.statusColumn?.key,owner:model.ownerColumn?.key,priority:model.priorityColumn?.key,date:due?.key,dates:[due,...dates.filter(c=>c!==due)].filter(Boolean).map(c=>c.key),detail:(cols.find(c=>c.key==="notes")||cols.find(c=>c.type==="text"&&c.key!=="serial"))?.key};}
  listView(rows,model){const k=this.fieldKeys(model);return `<section class="modern-list">${rows.map(row=>`<button class="list-card" data-action="edit" data-id="${this.attr(row.id)}"><span class="record-avatar">${this.escape(String(row.serial||"R")[0])}</span><span><strong>${this.escape(row.serial||"Untitled")}</strong>${k.detail?`<small>${this.escape(row[k.detail]||(k.detail==="notes"?"No notes":""))}</small>`:""}</span><span class="list-meta">${k.status&&row[k.status]?`<b class="status-chip">${this.escape(row[k.status])}</b>`:""}${k.dates.length?this.date(k.dates.map(key=>row[key]).find(Boolean)):""}</span>${icon("chevron")}</button>`).join("")}</section>`;}
  kanbanView(rows,model){const k=this.fieldKeys(model);const key=model.statusColumn?.key||model.groupColumn?.key;const groups=[...new Set([...(model.statusColumn?.options?.length?model.statusColumn.options:[]),...rows.map(r=>r[key]||"Unassigned")])];return `<section class="kanban-board">${groups.map(g=>{const items=rows.filter(r=>(r[key]||"Unassigned")===g);return `<div class="kanban-column"><header><strong>${this.escape(g)}</strong><span>${items.length}</span></header><div>${items.map(r=>`<button class="kanban-card" data-action="edit" data-id="${this.attr(r.id)}"><strong>${this.escape(r.serial)}</strong>${k.owner?`<small>${this.escape(model.valueText(model.ownerColumn,r[k.owner])||"Unassigned")}</small>`:""}${k.priority?`<span>${this.escape(r[k.priority]||"")}</span>`:""}</button>`).join("")||'<p class="kanban-empty">No records</p>'}</div></div>`}).join("")}</section>`;}
  calendarView(rows,model){const k=this.fieldKeys(model);const dateKey=k.date||"received";const dated=rows.filter(r=>r[dateKey]);return `<section class="calendar-view"><div class="calendar-head"><strong>Records by date</strong><small>${dated.length} scheduled</small></div><div class="calendar-grid">${dated.sort((a,b)=>String(a[dateKey]).localeCompare(String(b[dateKey]))).map(r=>`<button class="calendar-record" data-action="edit" data-id="${this.attr(r.id)}"><time>${this.date(r[dateKey])}</time><span><strong>${this.escape(r.serial)}</strong><small>${this.escape(k.status?r[k.status]||"":"")}</small></span></button>`).join("")||`<div class="calendar-empty">${k.date?"Add a date to a record to see it here.":"Add a Date column to this board to see records by date."}</div>`}${rows.filter(r=>!r[dateKey]).map(r=>`<button class="calendar-record" data-action="edit" data-id="${this.attr(r.id)}"><time>No date</time><strong>${this.escape(r.serial)}</strong></button>`).join("")}</div></section>`;}

  // bodies: board groups render one table (one header) with a <tbody> per group (BoardGroups.js).
  table(rows, model, group="", bodies=null) {
    const columns=model.visibleColumns, empty=!rows.length;
    const sorted=(key)=>model.sortKey===key&&!model.manualSort, filtered=(key)=>model.columnFilter?.key===key;
    const header=(column)=>{const label=this.escape(column.label),type=model.columnType(column.type)?.label||column.type,primary=column.key==="serial";return `<th data-column-key="${this.attr(column.key)}" class="${primary?"is-primary":"is-movable"}" ${sorted(column.key)?`aria-sort="${model.sortDirection==="asc"?"ascending":"descending"}"`:""} style="width:${this.colWidth(column)}px;min-width:${this.colWidth(column)}px"><div class="column-header" ${primary?"":`title="Drag to reorder"`}><span class="column-type-glyph" title="${this.escape(type)}" aria-hidden="true">${icon(columnTypeIcons[column.type]||"text")}</span><span class="column-label" title="${this.attr(column.description||column.label)}">${label}</span><button class="column-info-button" data-action="column-info" data-key="${this.attr(column.key)}" aria-label="About ${label}" title="${this.attr(this.columnGuidance(column))}">${icon("info")}</button>${sorted(column.key)?`<span class="column-indicator" title="Sorted ${model.sortDirection==="asc"?"ascending":"descending"}">${icon(model.sortDirection==="asc"?"arrowUp":"arrowDown")}</span>`:""}${filtered(column.key)?`<span class="column-indicator is-filter" title="Filtered">${icon("filter")}</span>`:""}${column.connection ? '<i class="connected-dot" title="Connection configured"></i>' : ""}<button class="column-menu-button" data-action="column-menu" data-key="${this.attr(column.key)}" aria-haspopup="menu" aria-label="Column options for ${label}" title="Column options">${icon("more")}</button></div><button class="column-resizer" data-action="resize-column" data-key="${this.attr(column.key)}" aria-label="Resize ${label}" title="Drag to resize; arrow keys to adjust"></button></th>`;};
    return `<div class="table-wrap ${empty?"is-empty":""}" tabindex="-1" role="region" aria-label="Records table, scroll to see more columns"><table class="editable-table"><thead><tr><th class="check-col"><input type="checkbox" aria-label="Select all visible records" data-action="select-all" ${!empty&&rows.every((row) => model.selected.has(row.id)) ? "checked" : ""} ${empty?"disabled":""}></th>${columns.map(header).join("")}<th class="add-column-col"><button class="add-column-button" data-action="add-column" aria-label="Add column" title="Add column">${icon("plus")}</button></th><th class="actions-col"><span class="sr-only">Record actions</span></th></tr></thead>${bodies ?? `<tbody>${rows.map((row) => this.row(row, model)).join("")}${this.quickAddRow(model, group, empty)}</tbody>`}</table></div>`;
  }
  quickAddRow(model, group = "", empty = false) {
    return `<tr class="quick-add-row"><td></td><td colspan="${model.visibleColumns.length + 2}"><button data-action="inline-add" data-group="${this.escape(group)}">${icon("plus")} Add record</button>${empty?`<span class="empty-table-note">No records yet</span>`:""}</td></tr>`;
  }
  row(row, model) {
    return `<tr data-record-context="${this.attr(row.id)}" class="${model.selected.has(row.id) ? "is-selected" : ""} ${row.pinned?"is-pinned":""}"><td class="check-col row-select-cell"><button type="button" class="row-drag-handle" data-action="row-drag" data-id="${this.attr(row.id)}" aria-label="Reorder ${this.escape(row.serial)}" title="Drag row to reorder. Alt + arrow keys also moves this row.">${icon("grip")}</button><input type="checkbox" aria-label="Select ${this.escape(row.serial)}" data-action="select" data-id="${this.attr(row.id)}" ${model.selected.has(row.id) ? "checked" : ""}></td>${model.visibleColumns.map((column) => this.cell(row,column,model)).join("")}<td class="add-column-col" aria-hidden="true"></td><td class="row-actions"><button class="row-open-button row-action" data-action="edit" data-id="${this.attr(row.id)}" aria-label="Open ${this.escape(row.serial||"record")}" title="Open record">${icon("expand")}</button><button class="row-more-button row-action" data-action="record-menu" data-id="${this.attr(row.id)}" aria-label="More actions for ${this.escape(row.serial||"record")}" title="More actions">${icon("more")}</button></td></tr>`;
  }


  // ---- Read-mode cells. Each cell is a focusable button; editing swaps in an editor for that one cell only.
  tone(value){
    const known={"new":"slate","in progress":"blue","working":"blue","working on it":"blue","doing":"blue","waiting":"amber","review":"amber","pending":"amber","on hold":"amber","completed":"green","done":"green","clear":"green","approved":"green","cancelled":"gray","canceled":"gray","defective":"red","stuck":"red","blocked":"red","low":"slate","medium":"amber","high":"orange","critical":"red","urgent":"red"};
    const key=String(value||"").trim().toLowerCase(); if(known[key])return known[key];
    const tones=["blue","teal","purple","pink","amber","green","orange","slate"]; let hash=0; for(const ch of key)hash=(hash*31+ch.charCodeAt(0))>>>0; return tones[hash%tones.length];
  }
  // A full-cell label (Status, Priority, single Dropdown): the label's colour fills the cell, text stays readable.
  cellLabel(value,color=""){const bg=HEX_COLOR.test(color)?color:TONE_HEX[this.tone(value)]||TONE_HEX.slate;return `<span class="cell-label" style="--label-bg:${bg};--label-fg:${readableOn(bg)}">${this.escape(value)}</span>`;}
  columnGuidance(column){return column.description||COLUMN_GUIDANCE[column.type]||"";}
  pill(value,color=""){ return `<span class="pill" data-tone="${this.tone(value)}" ${HEX_COLOR.test(color)?`style="--tone:${color}"`:""}>${this.escape(value)}</span>`; }
  // Several assignees: up to three avatars, then the name (one person) or a count.
  people(list,model){
    const names=list.map((v)=>model.personName(v)), shown=names.slice(0,3);
    const avatars=shown.map((n,i)=>`<span class="person-avatar ${model.isUserRef(list[i])&&model.people.get(list[i])?.isYou?"is-you":""}" aria-hidden="true">${this.escape(this.initials(n))}</span>`).join("");
    return `<span class="person people-stack" title="${this.escape(names.join(", "))}"><span class="avatar-stack">${avatars}${names.length>3?`<span class="person-avatar is-more" aria-hidden="true">+${names.length-3}</span>`:""}</span><span class="person-name">${this.escape(names.length===1?model.personLabel(list[0]):`${names.length} people`)}</span></span>`;
  }
  // Numbers: grouped for reading (1,234.5); the stored value is unchanged.
  number(value){const n=Number(value);return Number.isFinite(n)&&String(value).trim()!==""?FORMATS.number.format(n):String(value);}
  initials(name){ const parts=String(name||"").trim().split(/\s+/).filter(Boolean); return ((parts[0]?.[0]||"")+(parts.length>1?parts[1][0]:parts[0]?.[1]||"")).toUpperCase()||"?"; }
  person(name){ return `<span class="person"><span class="person-avatar" aria-hidden="true">${this.escape(this.initials(name))}</span><span class="person-name">${this.escape(name)}</span></span>`; }
  isChoiceColumn(column){ return ["status","priority","dropdown","group","owner"].includes(column.type); }
  cellText(row,column){ const value=row[column.key]; if(column.type==="files"){const n=this.model?.attachmentsFor?.(row.id,column.key).length||0;return n?`${n} file${n===1?"":"s"}`:"";} if(column.type==="checkbox")return value?"checked":"not checked"; if(column.type==="date"&&value)return this.date(value); if(this.model?.isMultiColumn?.(column))return this.model.valueText(column,value); return String(value??"").trim(); }
  cellDisplay(row,column,model){
    const value=row[column.key], has=model.hasValue(value), hint=EMPTY_HINT[column.type]||"", empty=(text="")=>`<span class="cell-empty" ${hint?`data-hint="${this.attr(hint)}"`:""}>${text}</span>`;
    if(column.type==="files")return this.filesCell(model,row,column);
    if(model.isMultiColumn(column)&&column.type==="dropdown"){const list=model.valueList(value);return list.length?`<span class="chip-list" title="${this.attr(list.join(", "))}">${list.slice(0,3).map((v)=>this.pill(v,model.optionColor(column,v))).join("")}${list.length>3?`<span class="chip-more">+${list.length-3}</span>`:""}</span>`:empty();}
    if(["status","priority","dropdown"].includes(column.type))return has?this.cellLabel(value,model.optionColor(column,value)):empty();
    if(column.type==="group")return has?this.pill(value):empty();
    if(column.type==="owner"){const list=model.valueList(value);return list.length?this.people(list,model):`<span class="cell-empty people-empty" data-hint="Assign">${icon("people")}</span>`;}
    if(column.type==="checkbox")return `<span class="cell-checkbox ${value?"is-checked":""}" aria-hidden="true">${icon("work")}</span>`;
    if(column.type==="date")return has?`<span class="cell-date">${icon("calendar")}<span>${this.date(value)}</span></span>`:empty();
    if(column.type==="number")return has?`<span class="cell-number" title="${this.escape(value)}">${this.escape(this.number(value))}</span>`:empty();
    return has?`<span class="cell-text">${this.escape(value)}</span>`:empty(column.key==="serial"?"Untitled":"");
  }
  cell(row,column,model){
    const value=row[column.key], text=this.cellText(row,column), href=["link","email","phone"].includes(column.type)?this.safeHref(value,column.type):"";
    const role=column.type==="checkbox"?`role="checkbox" aria-checked="${Boolean(value)}"`:this.isChoiceColumn(column)?'aria-haspopup="menu"':column.type==="files"?'aria-haspopup="dialog"':"";
    const fill=["status","priority"].includes(column.type)||(column.type==="dropdown"&&!model.isMultiColumn(column));
    return `<td class="cell ${column.type==="number"?"is-number":""} ${fill?"cell-fill":""}" data-column-key="${this.attr(column.key)}" data-type="${this.attr(column.type)}" data-value="${this.escape(column.type==="checkbox"?String(Boolean(value)):String(value??""))}" style="max-width:${this.colWidth(column)}px"><button type="button" class="cell-display" data-action="cell-open" data-id="${this.attr(row.id)}" data-field="${this.attr(column.key)}" ${role} aria-label="${this.escape(column.label)}: ${this.escape(text||"empty")}">${this.cellDisplay(row,column,model)}</button>${href?`<a class="cell-link" href="${this.attr(href)}" ${column.type==="link"?'target="_blank" rel="noopener noreferrer"':""} aria-label="${column.type==="email"?"Send email":column.type==="phone"?"Call":"Open link in a new tab"}" title="${column.type==="email"?"Send email":column.type==="phone"?"Call":"Open link"}">${icon(column.type==="email"?"mail":column.type==="phone"?"phone":"external")}</a>`:""}${column.key==="serial"&&this.commentsEnabled?this.commentButton(model,row):""}</td>`;
  }
  cellInput(row,column){
    const value=String(row[column.key]??""), attrs=`class="cell-input" data-action="cell-input" data-id="${this.attr(row.id)}" data-field="${this.attr(column.key)}" data-original="${this.escape(value)}" aria-label="Edit ${this.escape(column.label)}" ${column.required?"required":""}`;
    if(column.key==="notes")return `<textarea ${attrs} rows="3">${this.escape(value)}</textarea>`;
    const type={date:"date",number:"number",email:"email",phone:"tel",link:"url"}[column.type]||"text";
    return `<input ${attrs} type="${type}" value="${this.escape(value)}" ${type==="number"?'step="any"':""} placeholder="${column.key==="serial"?"Untitled":""}">`;
  }
  draftRow(model,group=""){
    return `<tr class="draft-row" data-group="${this.escape(group)}"><td class="check-col"></td>${model.visibleColumns.map(c=>c.key==="serial"?`<td class="cell is-editing"><input class="cell-input" data-action="draft-input" placeholder="Type a name, press Enter" title="Enter saves · Tab saves and moves on · Esc cancels" aria-label="New record name" maxlength="200" autocomplete="off"></td>`:`<td class="cell"></td>`).join("")}<td class="add-column-col"></td><td class="row-actions"></td></tr>`;
  }
  cellOptions(model,column){
    if(column.type!=="owner")return model.effectiveOptions(column);
    // Signed-in mode: colleagues from the server directory. Browser-only mode: this browser's contacts.
    if(model.people.size)return [...model.people.keys()];
    return [...new Set([model.profile.name,...model.members.map(m=>m.name)].filter(Boolean).map(String))];
  }
  // Cell picker. Single-value columns: choosing an option saves and closes. People and multi-select Dropdowns: each
  // tap adds or removes that value (saved straight away) and the picker stays open; Done closes it.
  showCellOptions(model,row,column,{query="",loading=false}={}){
    if(loading&&column.type==="owner"){document.querySelector("#overlay-root").innerHTML=`<div class="popover cell-options-popover" role="menu" aria-label="${this.escape(column.label)}" aria-busy="true" data-cell="${this.attr(row.id)}:${this.attr(column.key)}"><div class="popover-title"><strong>${this.escape(column.label)}</strong><small>Loading people…</small></div><div class="option-scroll" role="status">${Array.from({length:3},()=>'<span class="skeleton-option"><span class="skeleton skeleton-avatar"></span><span class="skeleton skeleton-text"></span></span>').join("")}<span class="sr-only">Loading people…</span></div></div>`;return;}
    const multi=model.isMultiColumn(column), chosen=multi?model.valueList(row[column.key]):[String(row[column.key]??"")].filter(Boolean);
    const options=this.cellOptions(model,column), list=[...new Set([...chosen.filter((v)=>!options.includes(v)),...options])];
    const label=(o)=>column.type==="owner"?model.personLabel(o):o;
    const ids=`data-id="${this.attr(row.id)}" data-field="${this.attr(column.key)}"`;
    const item=(o)=>{const on=chosen.includes(o);return `<button role="${multi?"menuitemcheckbox":"menuitemradio"}" aria-checked="${on}" class="cell-option ${on?"is-selected":""}" data-action="${multi?"toggle-cell-option":"set-cell-option"}" ${ids} data-value="${this.escape(o)}" data-label="${this.escape(label(o).toLowerCase())}">${column.type==="owner"?this.person(model.personLabel(o)):this.pill(o,column.type==="group"?"":model.optionColor(column,o))}${on?`<span class="option-check">${icon("work")}</span>`:""}</button>`;};
    const searchable=multi||column.type==="owner"||list.length>6;
    const empty=loading?'<p class="popover-copy" role="status">Loading people…</p>':column.type==="owner"?'<p class="popover-copy">No one to assign yet. Colleagues appear here once they have signed in to JARC.</p>':'<p class="popover-copy">No options yet.</p>';
    const editable=["status","priority","dropdown"].includes(column.type);
    const footer=[chosen.length?`<button data-action="set-cell-option" ${ids} data-value="">${icon("close")} Clear</button>`:"",editable?`<button data-action="edit-column-options" data-key="${this.attr(column.key)}">${icon("edit")} Edit labels</button>`:"",multi?`<button class="popover-done" data-action="close-overlay">Done</button>`:""].filter(Boolean).join("");
    document.querySelector("#overlay-root").innerHTML=`<div class="popover cell-options-popover" role="menu" aria-label="${this.escape(column.label)}" data-cell="${this.attr(row.id)}:${this.attr(column.key)}"><div class="popover-title"><strong>${this.escape(column.label)}</strong>${multi?`<small>${chosen.length?`${chosen.length} selected`:"Choose one or more"}</small>`:""}</div>${searchable?`<label class="option-search">${icon("search")}<input type="search" data-action="cell-option-search" value="${this.escape(query)}" placeholder="${column.type==="owner"?"Search people":"Search options"}" aria-label="${column.type==="owner"?"Search people":"Search options"}" autocomplete="off"></label>`:""}<div class="option-scroll">${list.map(item).join("")||empty}<p class="popover-copy option-no-match" hidden>No matches.</p></div>${footer?`<div class="popover-footer">${footer}</div>`:""}</div>`;
    const popover=document.querySelector(".cell-options-popover"); if(query)this.filterOptions(popover,query);
    (popover.querySelector('[data-action="cell-option-search"]')||popover.querySelector('.cell-option.is-selected')||popover.querySelector('.cell-option'))?.focus({preventScroll:true});
  }
  filterOptions(popover,query){const q=String(query||"").trim().toLowerCase();let shown=0;popover.querySelectorAll(".cell-option").forEach((b)=>{const hit=!q||b.dataset.label.includes(q);b.hidden=!hit;if(hit)shown++;});const none=popover.querySelector(".option-no-match");if(none)none.hidden=shown>0||!popover.querySelectorAll(".cell-option").length;}
  // Basic column filter dialog; the operators depend on the column type.
  filterOps(column){
    if(this.isChoiceColumn(column))return [["in","is any of"]];
    if(column.type==="checkbox")return [["checked","is checked"],["unchecked","is not checked"]];
    if(column.type==="number")return [["eq","="],["gt",">"],["lt","<"],["empty","is empty"],["not-empty","is not empty"]];
    if(column.type==="date")return [["on","is on"],["before","is before"],["after","is after"],["empty","is empty"],["not-empty","is not empty"]];
    return [["contains","contains"],["equals","is"],["empty","is empty"],["not-empty","is not empty"]];
  }
  showColumnFilter(model,key){
    const column=model.board.columns.find(c=>c.key===key); if(!column)return;
    const active=model.columnFilter?.key===key?model.columnFilter:null, ops=this.filterOps(column), choice=this.isChoiceColumn(column);
    const values=choice?[...new Set([...this.cellOptions(model,column),...model.rows.flatMap(r=>model.isMultiColumn(column)?model.valueList(r[key]):[String(r[key]??"")]).filter(Boolean)])]:[];
    const chosen=new Set(Array.isArray(active?.value)?active.value:[]);
    const inputType={number:"number",date:"date"}[column.type]||"text";
    this.overlay(`<form class="modal small-modal column-filter" data-action="column-filter-form"><div class="modal-head"><div><div class="eyebrow">Filter</div><h2>${this.escape(column.label)}</h2></div>${this.closeButton()}</div><input type="hidden" name="key" value="${this.attr(column.key)}">${choice?`<input type="hidden" name="op" value="in"><fieldset class="filter-values"><legend>Show records where ${this.escape(column.label)} is any of</legend>${values.map(v=>`<label class="checkbox-field"><input type="checkbox" name="value" value="${this.escape(v)}" ${chosen.has(v)?"checked":""}><span>${column.type==="owner"?this.escape(model.personLabel(v)):this.pill(v,model.optionColor(column,v))}</span></label>`).join("")||"<p>No values yet.</p>"}</fieldset>`:`<div class="form-grid"><label>Condition<select name="op">${ops.map(([v,t])=>`<option value="${v}" ${active?.op===v?"selected":""}>${t}</option>`).join("")}</select></label>${column.type==="checkbox"?"":`<label>Value<input name="value" type="${inputType}" value="${this.escape(active&&!Array.isArray(active.value)?active.value:"")}" ${inputType==="number"?'step="any"':""} autofocus></label>`}</div>`}<div class="modal-actions">${active?`<button type="button" class="button secondary" data-action="clear-column-filter">Clear filter</button>`:""}<span class="modal-spacer"></span><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Apply filter</button></div></form>`);
  }
  filterSummary(model){
    const f=model.columnFilter, column=f&&model.board.columns.find(c=>c.key===f.key); if(!column)return "";
    const op=Object.fromEntries(this.filterOps(column))[f.op]||f.op, value=Array.isArray(f.value)?f.value.map(v=>column.type==="owner"?this.model.personName(v):v).join(", "):["empty","not-empty","checked","unchecked"].includes(f.op)?"":column.type==="date"?this.date(f.value):f.value;
    return `${column.label} ${op}${value?" "+value:""}`;
  }
  crossBoardTable(rows) { return `<div class="table-wrap"><table><thead><tr><th>Record</th><th>Board</th><th>Workspace</th><th>Status</th><th>Priority</th><th>Due</th></tr></thead><tbody>${rows.map((row) => `<tr><td><button class="link-button" data-action="palette-record" data-id="${this.attr(row.id)}" data-board="${this.attr(row.boardId)}" data-workspace="${this.attr(row.workspaceId)}">${this.escape(row.serial)}</button></td><td>${this.escape(row.boardName)}</td><td>${this.escape(row.workspaceName||this.workspaceName(row.workspaceId))}</td><td>${row.status?`<span class="status status-${this.attr(String(row.status).toLowerCase())}">${this.escape(row.status)}</span>`:"-"}</td><td>${this.escape(row.priority||"-")}</td><td>${this.date(row.dueDate)}</td></tr>`).join("")}</tbody></table></div>`; }
  workspaceName(id) { return this.model?.workspaces.find(w=>w.id===id)?.name||"Workspace"; }
  blank(type, title, text, action = false) { return `<section class="empty-state ${type}"><div class="empty-visual"><span></span><span></span><span></span></div><h2>${title}</h2><p>${text}</p>${action ? `<button class="button primary" data-action="new-item">${icon("plus")} New record</button><button class="button secondary" data-action="import">${icon("import")} Import data</button>` : ""}</section>`; }

  showBoardForm(board,model=this.model) {
    this.overlay(`<form class="modal small-modal" data-action="board-form"><div class="modal-head"><div><div class="eyebrow">Workspace board</div><h2>${board?"Edit board":"Create board"}</h2></div>${this.closeButton()}</div><input type="hidden" name="id" value="${this.attr(board?.id||"")}"><div class="form-grid"><label class="full">Board name<input name="name" required maxlength="80" value="${this.escape(board?.name||"")}" placeholder="e.g. Service requests" autofocus></label>${!board?`<label class="full">Workspace<select name="workspace">${model.workspaces.filter(w=>!w.archived).map(w=>`<option value="${this.attr(w.id)}" ${w.id===model.workspace.id?"selected":""}>${this.escape(w.name)}</option>`).join("")}</select></label><label class="full">Start with<select name="template"><option value="blank">Blank — one Item column, add your own</option><option value="inventory">Inventory — ownership, invoices and dates</option><option value="tickets">Tickets — status, priority and deadlines</option><option value="projects">Projects — ownership and progress</option></select></label>`:""}<label class="full">Description<textarea name="description" rows="3" placeholder="What will this board help you manage?">${this.escape(board?.description||"")}</textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">${board?"Save board":"Create board"}</button></div></form>`);
  }

  showWorkspaceMenu(model) { document.querySelector("#overlay-root").innerHTML = `<div class="popover workspace-popover"><div class="popover-title"><strong>Switch workspace</strong><small>${model.workspaces.length} workspaces</small></div><label class="workspace-search">${icon("search")}<input placeholder="Search workspaces..." data-action="workspace-search"></label><div class="workspace-list">${model.workspaces.filter(w=>!w.archived).map((space) => `<button data-action="switch-workspace" data-id="${this.attr(space.id)}" class="${space.id === model.currentWorkspaceId ? "selected" : ""}"><span class="workspace-icon" style="background:${this.cssColor(space.color)}">${this.escape(space.name[0]||"")}</span><span><strong>${this.escape(space.name)}</strong><small>${space.boards.length} boards</small></span>${space.id === model.currentWorkspaceId ? "✓" : ""}</button>`).join("")}</div><div class="popover-footer"><button data-action="create-workspace">${icon("plus")} Create workspace</button><button data-action="workspace-manage">${icon("settings")} Manage workspaces</button></div></div>`; }
  showWorkspaceForm() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal workspace-form" data-action="workspace-form"><div class="modal-head"><div><div class="eyebrow">New workspace</div><h2>Create workspace</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><p class="modal-intro">Create a separate space for a team, department, or workflow.</p><div class="form-grid"><label class="full">Workspace name<input name="name" required maxlength="40" placeholder="e.g. Finance"></label><label>Icon<input name="icon" maxlength="2" value="W" placeholder="W"></label><label>Color<input name="color" type="color" value="#0f9489"></label><label class="full">Description<textarea name="description" rows="3" placeholder="What is this workspace for?"></textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary" type="submit">Create workspace</button></div></form></div>`; }
  showRecordMenu(row) { document.querySelector("#overlay-root").innerHTML = `<div class="popover record-menu-popover"><button data-action="edit" data-id="${this.attr(row.id)}">${icon("edit")} Edit record</button><button data-action="duplicate-record" data-id="${this.attr(row.id)}">${icon("copy")} Duplicate</button><button data-action="pin-item" data-id="${this.attr(row.id)}">${row.pinned?"Unpin":"Pin"} record</button>${this.model?.board?.groups?.length>1&&!this.model.board.source?.readOnly?`<button data-action="group-pick" data-id="${this.attr(row.id)}">${icon("group")} Move to group</button>`:""}<button data-action="move-record-board" data-id="${this.attr(row.id)}">${icon("board")} Move to board</button><button data-action="archive-item" data-id="${this.attr(row.id)}">${row.archived?"Restore":"Archive"}</button>${row.archived?"":`<button class="danger" data-action="delete" data-id="${this.attr(row.id)}">${icon("trash")} Delete</button>`}</div>`; }
  showBoardMenu(board,{current=false,archivedCount=0}={}) { document.querySelector("#overlay-root").innerHTML = `<div class="popover board-popover">${current?`<button data-action="edit-description">${icon("edit")} Edit description</button><button data-action="archived-view">${icon("archive")} Archived records <small class="menu-count">${archivedCount}</small></button><div class="menu-separator" role="separator"></div>`:""}<button data-action="open-board" data-id="${this.attr(board.id)}">${icon("board")} Open</button><button data-action="favorite-board" data-id="${this.attr(board.id)}">${icon("star")} ${board.favorite?"Unpin":"Pin"}</button><button data-action="rename-board" data-id="${this.attr(board.id)}">${icon("edit")} Rename</button><button data-action="duplicate-board" data-id="${this.attr(board.id)}">${icon("copy")} Duplicate</button><button data-action="move-board" data-id="${this.attr(board.id)}">${icon("board")} Move to workspace</button><button data-action="archive-board" data-id="${this.attr(board.id)}">${icon("archive")} ${board.archived?"Restore":"Archive"}</button><button class="danger" data-action="delete-board" data-id="${this.attr(board.id)}">${icon("trash")} Delete</button></div>`; }
  showSettings(model,section=model.settings.settingsSection||"appearance") {
    const sections=[["account","Account","people"],["profile","Profile","people"],["appearance","Appearance","sun"],["notifications","Notifications","bell"],["workspace","Workspace","board"],["members","Members","people"],["permissions","Permissions","lock"],["data","Data","records"],["security","Security","lock"]];
    const toggle=(key,title,help)=>`<label class="setting-row"><span><strong>${title}</strong><small>${help}</small></span><input type="checkbox" data-action="setting" data-key="${key}" ${model.settings[key]?"checked":""}></label>`;
    let body="";
    if(section==="appearance")body=`<h3>Theme</h3><p>Choose how JARC looks on this device.</p><div class="theme-grid">${["light","dark","system"].map(t=>`<button class="theme-option ${model.settings.theme===t?"selected":""}" data-action="theme" data-theme="${t}"><span class="theme-preview ${t}"><i></i><i></i><i></i></span><strong>${this.cap(t)}</strong></button>`).join("")}</div><label class="setting-row"><span><strong>Interface density</strong><small>Comfortable spacing or compact rows</small></span><select data-action="setting-select" data-key="density"><option ${model.settings.density==="comfortable"?"selected":""}>Comfortable</option><option ${model.settings.density==="compact"?"selected":""}>Compact</option></select></label><label class="setting-row"><span><strong>Text size</strong><small>Adjust text throughout the workspace</small></span><select data-action="setting-select" data-key="fontSize">${["small","normal","large"].map(v=>`<option ${model.settings.fontSize===v?"selected":""}>${this.cap(v)}</option>`).join("")}</select></label>${toggle("showIcons","Sidebar icons","Recognizable shortcuts in your navigation")}${toggle("showBoardCounts","Board counts","Show record counts beside boards")}${toggle("stickyFirstColumn","Sticky record name","Keep record names in view as you scroll")}${toggle("highContrast","High contrast","Stronger text and separators")}`;
    if(section==="workspace"&&!model.workspace)body=`<h3>No workspace yet</h3><p>Create a workspace to set its name, icon and colour here.</p><button class="button primary" data-action="create-workspace">${icon("plus")} Create workspace</button>`;
    else if(section==="workspace")body=`<form data-action="workspace-settings-form" class="form-grid"><label>Workspace name<input name="name" required value="${this.escape(model.workspace.name)}"></label><label>Icon<input name="icon" maxlength="2" value="${this.escape(model.workspace.icon||model.workspace.name[0])}"></label><label>Color<input type="color" name="color" value="${this.escape(model.workspace.color)}"></label><label class="full">Description<textarea name="description">${this.escape(model.workspace.description||"")}</textarea></label><button class="button primary">Save workspace</button></form><h3 class="section-break">All workspaces</h3><div class="manager-list">${model.workspaces.map(w=>`<div class="manager-row"><span><strong>${this.escape(w.name)}</strong><small>${w.boards.length} boards${w.archived?" · Archived":""}</small></span><button data-action="archive-workspace" data-id="${this.attr(w.id)}" data-archived="${w.archived?"0":"1"}">${w.archived?"Restore":"Archive"}</button><button class="danger" data-action="request-delete-workspace" data-id="${this.attr(w.id)}">Delete</button></div>`).join("")}</div><button class="button secondary" data-action="create-workspace">${icon("plus")} Create workspace</button>`;
    if(section==="members")body=`<p>This device keeps a contact directory for record ownership. Adding a contact does not send an invitation or grant remote access.</p><div class="manager-list">${model.members.map(m=>`<div class="manager-row"><span><strong>${this.escape(m.name)}</strong><small>${this.escape(m.email||m.status)} · ${this.escape(m.role)}</small></span>${m.role!=="Owner"?`<button class="danger" data-action="remove-member" data-id="${this.attr(m.id)}">Remove</button>`:"<small>Current account</small>"}</div>`).join("")}</div><button class="button primary" data-action="invite">${icon("plus")} Add local contact</button>`;
    if(section==="permissions")body=`<div class="notice"><strong>Local account access</strong><p>The signed-in account manages all records on this device. Contact roles are descriptive; this build has no server-enforced multi-user permissions.</p></div><h3>Current access</h3><p>Read and edit records, manage boards and workspaces, import and export data.</p>`;
    if(section==="account"||section==="profile")body=`<div class="account-card"><span class="profile large">${this.escape(model.profile.initials)}</span><div><h3>${this.escape(model.profile.name)}</h3><p>${this.escape(model.profile.email||"No email added")}</p></div></div><button class="button secondary" data-action="profile-settings">Edit profile and start screen</button><h3 class="section-break">Session</h3><p>Your board data stays on this browser when you sign out.</p><button class="button secondary" data-action="lock-session">Lock workspace</button><button class="button secondary" data-action="request-logout">Sign out</button>`;
    if(section==="notifications")body=`<h3>Activity inbox</h3><p>Notifications reflect changes made in this browser. There are no simulated assignments or mentions.</p>${toggle("muteActivity","Mute activity notifications","Keep board activity history without adding inbox entries")}<button class="button secondary" data-action="notifications">Open notification center</button>`;
    if(section==="data")body=`<h3>Keep a copy of your work</h3><p>Full JSON backups include all workspaces, records, columns, saved views, settings and local contacts.</p><button class="button primary" data-action="export-backup">${icon("export")} Export full backup</button><h3 class="section-break">Import records</h3><p>Preview CSV, JSON or pasted data, map columns, and review validation issues before adding records. For Excel, save the sheet as CSV first.</p><button class="button secondary" data-action="home-import">${icon("import")} Import data</button><h3 class="section-break">Storage</h3><p>Data is stored in this browser on this device. It is not synchronized to other users or computers.</p>`;
    if(section==="security")body=`<div class="notice"><strong>Local sign-in</strong><p>This project preserves its existing client-side sign-in. It is a local access screen, not server authentication or a security boundary for a shared deployment.</p></div><h3>Session protection</h3><p>Sessions lock after 30 minutes of inactivity. Repeated incorrect sign-in attempts pause access for 30 seconds.</p><button class="button secondary" data-action="lock-session">Lock workspace now</button>`;
    this.overlay(`<div class="settings-window"><nav class="settings-nav" aria-label="Settings sections"><div class="settings-brand"><span class="brand-mark">J</span><strong>Settings</strong></div>${sections.map(([id,label,ic])=>`<button data-action="settings-section" data-section="${id}" class="${id===section?"active":""}" title="${label}">${icon(ic)}<span>${label}</span></button>`).join("")}</nav><section class="settings-content"><div class="modal-head"><h2>${sections.find(s=>s[0]===section)?.[1]||"Settings"}</h2>${this.closeButton()}</div><div class="settings-body">${body}</div></section></div>`,"settings-overlay");
  }

  showInvite() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="invite-form"><div class="modal-head"><div><div class="eyebrow">Local directory</div><h2>Add local contact</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Email address<input name="email" type="email" required placeholder="name@company.com"></label><label class="full">Role<select name="role"><option>Admin</option><option selected>Editor</option><option>Viewer</option></select></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Add local contact</button></div></form></div>`; }
  showQuickChoice(title, options, action, id) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><h2>${this.escape(title)}</h2><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="choice-list">${options.map((value) => `<button data-action="${this.attr(action)}" data-id="${this.attr(id)}" data-value="${this.escape(value)}">${this.escape(value)}</button>`).join("")}</div></div></div>`; }
  showConfirm(title, text, action, payload = "", confirmLabel = "Confirm") { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal confirm-modal"><div class="confirm-icon">!</div><h2>${this.escape(title)}</h2><p>${this.escape(text)}</p><div class="modal-actions"><button class="button secondary" data-action="close-overlay">Cancel</button><button class="button danger-button" data-action="${this.attr(action)}" data-payload="${this.attr(payload)}">${this.escape(confirmLabel)}</button></div></div></div>`; }
  showMessage(title, text) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal confirm-modal"><div class="modal-head"><h2>${this.escape(title)}</h2><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><p>${this.escape(text).replaceAll("\n","<br>")}</p><div class="modal-actions"><button class="button primary" data-action="close-overlay">Done</button></div></div></div>`; }
  showGlobalSearch() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="global-search-form"><div class="modal-head"><div><div class="eyebrow">Every workspace</div><h2>Search all boards</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Search term <input name="term" required autofocus placeholder="Serial, invoice, or note"></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Search</button></div></form></div>`; }
  showGroupManager(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><div><div class="eyebrow">Board structure</div><h2>Manage groups</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="manager-list">${model.board.groups.map((group) => `<div class="manager-row"><input data-role="group-name" data-old="${this.escape(group)}" value="${this.escape(group)}"><button data-action="save-group" data-old="${this.escape(group)}">Save</button><button class="danger" data-action="request-delete-group" data-group="${this.escape(group)}" ${model.board.groups.length === 1 ? "disabled" : ""}>Delete</button></div>`).join("")}</div><form class="inline-form" data-action="add-group-form"><input name="name" required placeholder="New group name"><button class="button primary">Add group</button></form></div></div>`; }
  showColumnManager(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal column-modal"><div class="modal-head"><div><div class="eyebrow">Board schema</div><h2>Columns</h2><p>Each board owns its column types, labels, order, and connection keys.</p></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div>${(()=>{const hidden=model.board.columns.filter(c=>!model.columnShown(c));return hidden.length?`<section class="hidden-columns" aria-label="Hidden columns"><div class="hidden-columns-head"><h3>Hidden columns <small>${hidden.length}</small></h3>${hidden.length>1?`<button type="button" class="button ghost" data-action="show-all-columns">Show all</button>`:""}</div>${hidden.map(c=>`<div class="hidden-column-row"><span>${icon(columnTypeIcons[c.type]||"text")}<strong>${this.escape(c.label)}</strong><small>${this.escape(model.columnType(c.type)?.label||c.type)}</small></span><button type="button" class="button secondary" data-action="show-column" data-key="${this.attr(c.key)}">Show</button></div>`).join("")}</section>`:"";})()}<div class="column-manager-list">${model.board.columns.map((column,index)=>`<button data-action="column-editor" data-key="${this.attr(column.key)}"><span class="column-type-icon">${index+1}</span><span><strong>${this.escape(column.label)}</strong><small>${this.escape(model.columnType(column.type)?.label||column.type)} · ${column.visible!==false?"Visible":"Hidden"}</small></span><b>${icon("chevron")}</b></button>`).join("")}</div><div class="modal-actions"><button class="button primary" data-action="add-column">+ Add column</button></div></div></div>`; }
  // Categorized column-type chooser. mode "add" leads to the name step; mode "change" converts an existing column.
  showAddColumn(model) { this.showColumnChooser(model,{mode:"add"}); }
  showColumnChooser(model,{mode="add",key=""}={}) {
    const column=mode==="change"?model.board.columns.find(c=>c.key===key):null;
    const types=model.columnTypes.filter(t=>t.type!=="files"||(mode!=="change"&&model.filesAvailable()));
    const categories=[...new Set(types.map(t=>t.category))];
    const option=(t)=>{const current=column?.type===t.type;return `<button type="button" class="chooser-option ${current?"is-current":""}" data-action="${mode==="change"?"choose-new-type":"choose-column-type"}" data-type="${this.attr(t.type)}" data-key="${this.escape(key)}" data-search="${this.escape((t.label+" "+t.description+" "+t.category).toLowerCase())}" ${current?'disabled aria-current="true"':""}><span class="chooser-icon">${icon(columnTypeIcons[t.type]||"text")}</span><span><strong>${t.label}${current?" <em>Current</em>":""}</strong><small>${t.description}</small></span></button>`;};
    this.overlay(`<div class="modal column-chooser"><div class="modal-head"><div><div class="eyebrow">${column?this.escape(column.label):this.escape(model.board.name)}</div><h2>${column?"Change column type":"Add column"}</h2></div>${this.closeButton()}</div><label class="chooser-search">${icon("search")}<input data-action="column-type-search" placeholder="Search column types" aria-label="Search column types" autocomplete="off" autofocus></label><div class="chooser-groups">${categories.map(cat=>`<section class="chooser-group"><h3>${cat}</h3><div class="chooser-grid">${types.filter(t=>t.category===cat).map(option).join("")}</div></section>`).join("")}<p class="chooser-empty" hidden>No column types match your search.</p></div>${column?`<p class="chooser-note">Values that don't fit the new type are only cleared after you confirm. Undo is available afterwards.</p>`:""}</div>`);
  }
  showColumnNameStep(model,type) {
    const meta=model.columnType(type), optionable=["status","dropdown","priority"].includes(type), defaults=model.newColumnOptions(type);
    this.overlay(`<form class="modal column-chooser column-name-step" data-action="create-column-form"><div class="modal-head"><div><div class="eyebrow">${icon(columnTypeIcons[type]||"text")} ${meta.label} column</div><h2>Name your column</h2></div>${this.closeButton()}</div><input type="hidden" name="type" value="${this.attr(type)}"><div class="form-grid"><label class="full">Column name<input name="label" required maxlength="50" value="${this.escape(model.uniqueColumnLabel(meta.label))}" autofocus></label>${optionable?`<label class="full">Options<input name="options" value="${this.escape(defaults.join(", "))}" placeholder="${type==="dropdown"?"e.g. North, South, East":"Option one, Option two"}"><small>Separate options with commas. You can edit them later from the column menu.</small></label>`:""}${type==="dropdown"?`<label class="checkbox-label full"><input type="checkbox" name="multiple"> Allow several values per record</label>`:""}</div><div class="modal-actions"><button type="button" class="button secondary" data-action="add-column">${icon("left")} Back</button><span class="modal-spacer"></span><button class="button primary">Create column</button></div></form>`);
  }
  showColumnMenu(model,key) {
    const c=model.board.columns.find(item=>item.key===key); if(!c)return;
    const primary=c.key==="serial", optionable=["status","dropdown","priority"].includes(c.type), reason=(text)=>`<small class="menu-reason">${text}</small>`;
    const index=model.board.columns.indexOf(c), sortedHere=model.sortKey===c.key&&!model.manualSort, filteredHere=model.columnFilter?.key===c.key, firstMovable=index<=1, lastColumn=index===model.board.columns.length-1;
    const item=(action,ic,label,extra="")=>`<button role="menuitem" data-action="${action}" data-key="${this.attr(c.key)}" ${extra}>${icon(ic)} ${label}</button>`, section=(title)=>`<div class="menu-section-label" role="presentation">${title}</div>`;
    document.querySelector("#overlay-root").innerHTML=`<div class="popover column-menu-popover" role="menu" aria-label="${this.attr(c.label)} column"><div class="popover-title"><strong>${this.escape(c.label)}</strong><small>${this.escape(model.columnType(c.type)?.label||c.type)}${primary?" · Primary":""}</small></div>${section("Column")}${item("rename-column","edit","Name and description")}${optionable?item("edit-column-options","list","Edit labels"):""}${c.type==="dropdown"?item("toggle-column-multiple","list",c.multiple?"Allow one value only":"Allow several values"):""}${c.type==="group"?`<button role="menuitem" data-action="manage-groups">${icon("group")} Manage groups</button>`:""}${primary||c.type==="files"?"":item("change-column-type","swap","Change type")}${item("column-width","columns","Column width…")}${primary?"":item("duplicate-column","copy","Duplicate column")}${item("column-editor","settings","More settings")}${section("View")}${item("sort-column","arrowUp",`Sort ascending${sortedHere&&model.sortDirection==="asc"?reason("Active"):""}`,'data-direction="asc"')}${item("sort-column","arrowDown",`Sort descending${sortedHere&&model.sortDirection==="desc"?reason("Active"):""}`,'data-direction="desc"')}${sortedHere?`<button role="menuitem" data-action="clear-sort">${icon("close")} Clear sort</button>`:""}${c.type==="files"?"":item("filter-column","filter",`Filter…${filteredHere?reason("Active"):""}`)}${filteredHere?`<button role="menuitem" data-action="clear-column-filter">${icon("close")} Clear filter</button>`:""}${item("hide-column","hide",`Hide column${primary?reason("Always shown"):""}`,primary?"disabled":"")}${primary?"":`${section("Arrange")}${item("move-column-menu","left","Move left",`data-direction="left" ${firstMovable?"disabled":""}`)}${item("move-column-menu","right","Move right",`data-direction="right" ${lastColumn?"disabled":""}`)}`}<div class="menu-separator" role="separator"></div><button role="menuitem" class="danger" data-action="request-delete-column" data-key="${this.attr(c.key)}" ${primary?"disabled":""}>${icon("trash")} Delete column${primary?reason("Required"):""}</button></div>`;
  }
  // The column's description (or default guidance for its type), from the header's ⓘ button.
  showColumnInfo(model,key){const c=model.board.columns.find(item=>item.key===key);if(!c)return;document.querySelector("#overlay-root").innerHTML=`<div class="popover column-info-popover" role="dialog" aria-label="About ${this.attr(c.label)}"><div class="popover-title"><strong>${this.escape(c.label)}</strong><small>${this.escape(model.columnType(c.type)?.label||c.type)} column</small></div><p class="popover-copy">${this.escape(this.columnGuidance(c))}</p>${c.description?"":'<p class="popover-copy muted-copy">No description yet.</p>'}<div class="popover-footer"><button data-action="rename-column" data-key="${this.attr(c.key)}">${icon("edit")} ${c.description?"Edit description":"Add a description"}</button></div></div>`;}
  // ---- Files columns: thumbnails in the cell; a panel to add, preview, download and remove files.
  fileSize(bytes){const n=Number(bytes)||0;return n<1024?`${n} B`:n<1048576?`${Math.round(n/1024)} KB`:`${(n/1048576).toFixed(n<10485760?1:0)} MB`;}
  fileKind(type){return type==="application/pdf"?"PDF":type==="image/png"?"PNG":type==="image/webp"?"WebP":"JPEG";}
  fileThumb(model,a,{large=false}={}){
    const url=model.attachmentUrl(a.id);
    return a.type==="application/pdf"||!url?`<span class="file-thumb is-doc ${large?"is-large":""}" aria-hidden="true">${icon("file")}<em>${this.fileKind(a.type)}</em></span>`:`<span class="file-thumb ${large?"is-large":""}" aria-hidden="true"><img src="${this.attr(url)}" alt="" loading="lazy" decoding="async" draggable="false"></span>`;
  }
  filesCell(model,row,column){
    const list=model.attachmentsFor(row.id,column.key);
    const boardId=model.serverId(model.board?.id);
    if(!list.length&&model.attachmentLoading?.has(boardId))return `<span class="file-thumb skeleton file-skeleton" aria-hidden="true"></span><span class="sr-only">Loading files</span>`;
    if(!list.length&&model.attachmentErrors?.has(boardId))return `<span class="cell-empty files-error" title="Files couldn't load. Open to try again.">${icon("paperclip")}<em aria-hidden="true">!</em></span><span class="sr-only">Files couldn't load</span>`;
    if(!list.length)return `<span class="cell-empty files-empty" data-hint="Add files">${icon("paperclip")}</span>`;
    const shown=list.slice(0,3);
    return `<span class="file-chips" title="${this.attr(list.map(a=>a.name).join(", "))}">${shown.map(a=>this.fileThumb(model,a)).join("")}${list.length>3?`<span class="chip-more">+${list.length-3}</span>`:""}${list.length===1?`<span class="file-chip-name">${this.escape(list[0].name)}</span>`:""}</span>`;
  }
  // state: { uploads, confirm (attachment ID awaiting confirmation), notice }
  showFilesPanel(model,row,column,{uploads=[],confirm=null,notice="",fresh=new Set()}={}){
    const boardId=model.serverId(model.board?.id), loadingFiles=model.attachmentLoading?.has(boardId), failedFiles=model.attachmentErrors?.has(boardId);
    const list=model.attachmentsFor(row.id,column.key), cell=`${row.id}:${column.key}`, ids=`data-id="${this.attr(row.id)}" data-field="${this.attr(column.key)}"`;
    const when=(iso)=>{const d=new Date(iso);return Number.isNaN(d.getTime())?"":d.toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"});};
    const available=model.filesAvailable();
    const upload=(u)=>`<li class="file-row ${u.state==="failed"?"is-failed":"is-uploading"}" data-upload="${this.attr(u.id)}"><span class="file-thumb is-doc" aria-hidden="true">${icon(u.state==="failed"?"close":"upload")}</span><span class="file-meta"><strong>${this.escape(u.name)}</strong>${u.state==="failed"?`<small class="file-error" role="alert">${this.escape(u.error)}</small>`:`<small><span class="upload-text">${this.fileSize(u.size)} · Uploading ${Math.round(u.progress*100)}%</span></small><progress max="100" value="${Math.round(u.progress*100)}" aria-label="Uploading ${this.attr(u.name)}"></progress>`}</span><span class="file-actions">${u.state==="failed"&&u.retryable?`<button type="button" class="icon-button" data-action="retry-upload" ${ids} data-upload="${this.attr(u.id)}" aria-label="Try ${this.attr(u.name)} again" title="Try again">${icon("refresh")}</button>`:""}${u.state==="failed"?`<button type="button" class="icon-button" data-action="dismiss-upload" ${ids} data-upload="${this.attr(u.id)}" aria-label="Dismiss" title="Dismiss">${icon("close")}</button>`:""}</span></li>`;
    const file=(a)=>confirm===a.id
      ?`<li class="file-row is-confirming"><span class="file-meta"><strong>Remove “${this.escape(a.name)}”?</strong><small>Everyone loses access to it. This can't be undone.</small></span><span class="file-actions"><button type="button" class="button secondary small" data-action="cancel-remove-file" ${ids}>Cancel</button><button type="button" class="button danger small" data-action="confirm-remove-file" ${ids} data-file="${this.attr(a.id)}" autofocus>Remove</button></span></li>`
      :`<li class="file-row ${fresh.has(a.id)?"is-fresh":""}"><button type="button" class="file-open" data-action="preview-file" ${ids} data-file="${this.attr(a.id)}" aria-label="Preview ${this.attr(a.name)}">${this.fileThumb(model,a)}<span class="file-meta"><strong>${this.escape(a.name)}${fresh.has(a.id)?`<span class="file-done">${icon("work")} Uploaded</span>`:""}</strong><small>${this.fileKind(a.type)} · ${this.fileSize(a.size)}${a.uploadedByName?` · ${this.escape(a.uploadedByName)}`:""}${when(a.createdAt)?` · ${when(a.createdAt)}`:""}</small></span></button><span class="file-actions"><a class="icon-button" data-action="download-file" data-name="${this.attr(a.name)}" href="${this.attr(model.attachmentUrl(a.id,{download:true}))}" download="${this.attr(a.name)}" aria-label="Download ${this.attr(a.name)}" title="Download">${icon("download")}</a><button type="button" class="icon-button" data-action="request-remove-file" ${ids} data-file="${this.attr(a.id)}" aria-label="Remove ${this.attr(a.name)}" title="Remove">${icon("trash")}</button></span></li>`;
    const picker=available?`<div class="file-drop" data-drop-cell="${this.attr(cell)}"><label class="button primary small file-pick">${icon("upload")} Add files<input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,application/pdf,image/jpeg,image/png,image/webp" data-action="files-input" ${ids} class="sr-only"></label><small>or drop them here · PDF, JPEG, PNG, WebP · up to 10 MB each</small></div>`:`<p class="popover-copy">Files are stored on the JARC server. Sign in with Microsoft to add or open them.</p>`;
    document.querySelector("#overlay-root").innerHTML=`<div class="popover files-popover" role="dialog" aria-label="${this.attr(column.label)} files" data-cell="${this.attr(cell)}"><div class="popover-title"><strong>${this.escape(column.label)}</strong><small>${list.length?`${list.length} file${list.length===1?"":"s"}`:loadingFiles?"Loading…":failedFiles?"Couldn't load":"No files yet"}</small></div>${picker}${notice?`<p class="popover-copy file-notice" role="status">${this.escape(notice)}</p>`:""}${loadingFiles&&!list.length?`<div class="file-list-skeleton" aria-busy="true" role="status" aria-label="Loading files">${Array.from({length:2},()=>`<div class="file-row"><span class="skeleton file-thumb"></span><span class="file-meta"><span class="skeleton skeleton-text" style="width:62%"></span><span class="skeleton skeleton-text is-small" style="width:38%"></span></span></div>`).join("")}</div>`:""}${failedFiles?`<div class="file-load-error" role="alert"><span>Files couldn't load.</span><button type="button" class="button secondary small" data-action="retry-attachments">Try again</button></div>`:""}<ul class="file-list" aria-live="polite">${uploads.map(upload).join("")}${list.map(file).join("")}</ul></div>`;
  }
  updateUploadProgress(u){const row=document.querySelector(`.file-row[data-upload="${CSS.escape(u.id)}"]`);if(!row)return;const pct=Math.round(u.progress*100);const bar=row.querySelector("progress");if(bar)bar.value=pct;const text=row.querySelector(".upload-text");if(text)text.textContent=`${this.fileSize(u.size)} · ${pct>=100?"Saving…":`Uploading ${pct}%`}`;}
  showFilePreview(model,row,column,a){
    const url=model.attachmentUrl(a.id), ids=`data-id="${this.attr(row.id)}" data-field="${this.attr(column.key)}"`;
    const body=a.type==="application/pdf"?`<iframe class="file-preview-frame" src="${this.attr(url)}" title="${this.attr(a.name)}"></iframe>`:`<img class="file-preview-image" src="${this.attr(url)}" alt="${this.attr(a.name)}">`;
    this.overlay(`<div class="modal file-preview-modal"><div class="modal-head"><div><div class="eyebrow">${this.escape(column.label)} · ${this.fileKind(a.type)} · ${this.fileSize(a.size)}${a.uploadedByName?` · ${this.escape(a.uploadedByName)}`:""}</div><h2>${this.escape(a.name)}</h2></div>${this.closeButton()}</div><div class="file-preview-body is-loading" data-preview-state="loading">${body}<div class="file-preview-status" role="status"><span class="loading-spinner" aria-hidden="true"></span><span>Loading preview…</span></div><div class="file-preview-failed" role="alert">${icon("file")}<span>This preview can't be shown here. Download the file to open it.</span></div></div><div class="modal-actions"><button type="button" class="button secondary" data-action="back-to-files" ${ids}>${icon("left")} All files</button><a class="button secondary" href="${this.attr(url)}" target="_blank" rel="noopener">${icon("eye")} Open in new tab</a><a class="button primary" data-action="download-file" data-name="${this.attr(a.name)}" href="${this.attr(model.attachmentUrl(a.id,{download:true}))}" download="${this.attr(a.name)}">${icon("download")} Download</a></div></div>`);
  }
  showRenameColumn(model,key) {
    const c=model.board.columns.find(item=>item.key===key); if(!c)return;
    this.overlay(`<form class="modal small-modal" data-action="rename-column-form"><div class="modal-head"><div><div class="eyebrow">${this.escape(model.columnType(c.type)?.label||c.type)} column</div><h2>Edit column</h2></div>${this.closeButton()}</div><input type="hidden" name="key" value="${this.attr(c.key)}"><div class="form-grid"><label class="full">Column name<input name="label" required maxlength="50" value="${this.escape(c.label)}" autofocus></label><label class="full">Description <small class="field-note">optional — shown from the column's ⓘ button</small><textarea name="description" rows="3" maxlength="500" placeholder="${this.attr(COLUMN_GUIDANCE[c.type]||"What belongs in this column?")}">${this.escape(c.description||"")}</textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save</button></div></form>`);
  }
  optionRow(value="",count=0,color="") { const name=this.escape(value||"option"); return `<div class="option-row"><span class="option-swatch" style="${HEX_COLOR.test(color)?`--tone:${color}`:""}" data-tone="${this.tone(value)}" aria-hidden="true"></span><input class="option-name" data-from="${this.escape(value)}" value="${this.escape(value)}" placeholder="Label name" aria-label="Label name" maxlength="40"><select class="option-color" aria-label="Colour for ${name}" data-action="option-color"><option value="">Automatic</option>${LABEL_COLORS.map(([hex,label])=>`<option value="${hex}" ${color.toLowerCase()===hex.toLowerCase()?"selected":""}>${label}</option>`).join("")}</select><small class="option-usage">${count?`${count} record${count===1?"":"s"}`:""}</small><span class="option-order"><button type="button" class="icon-button" data-action="move-option-row" data-direction="up" aria-label="Move ${name} up" title="Move up">${icon("arrowUp")}</button><button type="button" class="icon-button" data-action="move-option-row" data-direction="down" aria-label="Move ${name} down" title="Move down">${icon("arrowDown")}</button></span><button type="button" class="icon-button" data-action="remove-option-row" aria-label="Remove ${name}" title="Remove label">${icon("trash")}</button></div>`; }
  showOptionEditor(model,key) {
    const c=model.board.columns.find(item=>item.key===key); if(!c)return;
    this.overlay(`<form class="modal small-modal option-editor" data-action="column-options-form"><div class="modal-head"><div><div class="eyebrow">${this.escape(c.label)}</div><h2>Edit labels</h2><p>Renaming a label updates every record that uses it. Removing one clears it from those records.</p></div>${this.closeButton()}</div><input type="hidden" name="key" value="${this.attr(c.key)}"><div class="option-list">${model.effectiveOptions(c).map(o=>this.optionRow(o,model.rows.filter(r=>model.valueList(r[key]).includes(o)).length,model.optionColor(c,o))).join("")}</div><button type="button" class="button ghost add-option-button" data-action="add-option-row">${icon("plus")} Add label</button><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save options</button></div></form>`);
  }
  showGroupHelp() {
    document.querySelector("#overlay-root").innerHTML=`<div class="popover group-help-popover"><div class="popover-title"><strong>No group column yet</strong></div><p class="popover-copy">Add a Group column to sort records into this board's groups, then turn grouping on.</p><button data-action="add-group-column">${icon("plus")} Add group column</button></div>`;
  }
  showColumnEditor(model, key) { const column=model.board.columns.find((item)=>item.key===key); if(!column)return; document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><form class="settings-drawer column-settings-drawer" data-action="edit-column-form"><div class="modal-head"><div><div class="eyebrow">${this.escape(column.type)} column</div><h2>Edit column</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><input type="hidden" name="key" value="${this.attr(column.key)}"><div class="form-grid"><label class="full">Header name<input name="label" required value="${this.escape(column.label)}"></label><label class="full">Description<textarea name="description" rows="3" maxlength="500" placeholder="${this.attr(COLUMN_GUIDANCE[column.type]||"What belongs in this column?")}">${this.escape(column.description||"")}</textarea></label>${["status","priority","dropdown","owner","files","checkbox"].includes(column.type)?`<p class="field-note full">${["status","priority","dropdown"].includes(column.type)?"Labels, colours and order: use Edit labels in the column menu.":""}</p>`:`<label>Default value<input name="defaultValue" value="${this.escape(column.defaultValue)}"></label>`}<label class="full">Field identifier (metadata only)<input name="connection" value="${this.escape(column.connection)}" placeholder="Optional field identifier"></label><label class="checkbox-label"><input type="checkbox" name="visible" ${column.visible?"checked":""}> Visible</label><label class="checkbox-label"><input type="checkbox" name="required" ${column.required?"checked":""} ${column.key==="serial"?"disabled":""}> Required</label></div><div class="column-actions"><button type="button" data-action="move-column" data-key="${this.attr(column.key)}" data-direction="left">Move left</button><button type="button" data-action="move-column" data-key="${this.attr(column.key)}" data-direction="right">Move right</button><button type="button" data-action="duplicate-column" data-key="${this.attr(column.key)}">Duplicate</button><button type="button" class="danger" data-action="request-delete-column" data-key="${this.attr(column.key)}" ${column.key==="serial"?"disabled":""}>Delete</button></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save column</button></div></form></div>`; }
  showSavedViews(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><div><div class="eyebrow">Reusable filters</div><h2>Saved views</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="manager-list">${model.board.savedViews.map((view) => `<div class="manager-row"><button class="view-name" data-action="apply-saved-view" data-id="${this.attr(view.id)}">${this.escape(view.name)}<small>${view.status} · ${view.grouped ? "Grouped" : "Table"}</small></button><button class="danger" data-action="delete-saved-view" data-id="${this.attr(view.id)}">Delete</button></div>`).join("") || '<p class="muted-copy">No saved views yet.</p>'}</div><form class="inline-form" data-action="save-view-form"><input name="name" required placeholder="Name current filters" aria-label="Saved view name"><button class="button primary">Save current view</button></form></div></div>`; }
  showProfileMenu(model, auth) { const avatar=this.safeImage(model.profile.avatar) ? `<img src="${this.attr(this.safeImage(model.profile.avatar))}" alt="">` : this.escape(model.profile.initials); document.querySelector("#overlay-root").innerHTML = `<div class="profile-popover modern-profile"><div class="profile-summary"><span class="profile large" style="background:${this.cssColor(model.profile.color,"#0f9489")}">${avatar}</span><div><strong>${this.escape(model.profile.name)}</strong>${model.profile.email?`<small class="profile-email">${this.escape(model.profile.email)}</small>`:""}<small>${this.escape(model.profile.role)}</small><em><i class="presence presence-${this.attr(String(model.profile.presence).toLowerCase())}"></i>${this.escape(model.profile.presence)}</em></div></div><div class="profile-menu-section"><button data-action="profile-settings">${icon("people")} View profile</button><button data-action="settings">${icon("settings")} Account settings</button><button data-action="notifications">${icon("bell")} Notifications <small>${model.unreadCount}</small></button></div><div class="profile-menu-section presence-picker"><span>Status</span>${["Available","Busy","Focus","Offline"].map((value)=>`<button data-action="set-presence" data-value="${value}" class="${model.profile.presence===value?"active":""}"><i class="presence presence-${value.toLowerCase()}"></i>${value}</button>`).join("")}</div><div class="profile-menu-section"><button data-action="workspace-menu">${icon("board")} Switch workspace</button><button data-action="workspace-manage">${icon("settings")} Manage workspace</button></div><div class="profile-menu-section"><button class="danger" data-action="request-logout">Sign out</button></div></div>`; }
  showProfileSettings(model) { const avatar=this.safeImage(model.profile.avatar) ? `<img src="${this.attr(this.safeImage(model.profile.avatar))}" alt="">` : this.escape(model.profile.initials); document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><form class="settings-drawer" data-action="profile-form"><div class="modal-head"><div><div class="eyebrow">Personal account</div><h2>Profile</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><section class="avatar-editor"><span class="profile xlarge" style="background:${this.cssColor(model.profile.color,"#0f9489")}">${avatar}</span><div><button type="button" class="button secondary" data-action="choose-avatar">Upload photo</button>${this.safeImage(model.profile.avatar)?'<button type="button" class="text-danger" data-action="remove-avatar">Remove</button>':""}<small>PNG, JPG, or WebP up to 1 MB</small></div></section><section class="profile-fields"><label>Username-synced name<input name="name" readonly value="${this.escape(model.profile.name)}"></label><label>Email<input name="email" type="email" value="${this.escape(model.profile.email)}" placeholder="name@company.com"></label><label>Role<input name="role" value="${this.escape(model.profile.role)}"></label><label>Avatar color<input name="color" type="color" value="${this.cssColor(model.profile.color,"#0f9489")}"></label><label>Start screen<select name="startScreen">${["Last opened board","Home","My work"].map((value)=>`<option ${model.profile.startScreen===value?"selected":""}>${value}</option>`).join("")}</select></label></section><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save profile</button></div></form></div>`; }
  showNotifications(model,filter="all",{loading=false}={}) {
    if(model.feed||loading)return this.showFeed(model,filter,{loading});
    const items=model.notifications.filter(n=>filter==="all"||n.type===filter);
    this.overlay(`<aside class="settings-drawer notification-drawer"><div class="modal-head"><div><div class="eyebrow">Your inbox</div><h2>Notifications</h2></div>${this.closeButton()}</div><div class="notification-tabs">${["all","mentions","assigned"].map(f=>`<button data-action="notification-filter" data-filter="${f}" class="${f===filter?"active":""}">${this.cap(f)}</button>`).join("")}<button data-action="mark-notifications">Mark all read</button></div><div class="notification-list">${items.map(n=>`<button class="notification-item ${n.read?"":"unread"}" data-action="open-notification" data-board="${this.attr(n.boardId)}" data-workspace="${this.attr(n.workspaceId)}"><span class="record-avatar">${icon("bell")}</span><span><strong>${this.escape(n.text)}</strong><small>${this.relative(n.at)}</small></span></button>`).join("")||`<div class="quiet-empty">${icon("bell")}<span><strong>You're all caught up</strong><small>No ${filter==="all"?"new activity":filter} to show.</small></span></div>`}</div></aside>`,"drawer-overlay");
  }

  feedItem(model,n){
    const mine=Boolean(n.actorId&&n.actorId===model.me), who=mine?"You":n.actorName||"Unknown user", where=[n.boardName||n.workspaceName,n.recordName].filter(Boolean).join(" · ");
    const when=new Date(n.at), full=Number.isNaN(when.getTime())?"":FORMATS.stamp.format(when);
    return `<button class="notification-item ${model.feedUnread(n)?"unread":""} ${mine?"is-mine":""}" data-action="open-notification" data-board="${this.attr(n.boardId||"")}" data-workspace="${this.attr(n.workspaceId||"")}"><span class="person-avatar actor-avatar ${n.actorName?"":"is-unknown"} ${mine?"is-you":""}" aria-hidden="true">${this.escape(n.actorName?this.initials(n.actorName):"?")}</span><span class="notification-body"><strong><span class="actor-name">${this.escape(who)}</span> ${this.escape(n.text.charAt(0).toLowerCase()+n.text.slice(1))}</strong>${where?`<small class="notification-where">${this.escape(where)}</small>`:""}<small><time datetime="${this.attr(n.at)}" title="${this.attr(full)}">${this.relative(n.at)}</time></small></span></button>`;
  }
  showFeed(model,filter="all",{loading=false}={}){
    const feed=model.feed||[], items=filter==="all"?feed:filter==="assigned"?feed.filter(n=>n.actorId!==model.me&&(n.assigned||[]).some(a=>a.to.includes(model.me)&&!a.from.includes(model.me))):feed.filter(n=>n.actorId!==model.me&&((n.mentions||[]).includes(model.me)||n.replyTo===model.me));
    const body=loading&&!model.feed?this.feedSkeleton():items.map(n=>this.feedItem(model,n)).join("")||`<div class="quiet-empty">${icon("bell")}<span><strong>You're all caught up</strong><small>${filter==="mentions"?"When a colleague mentions you or replies to your update, it appears here.":filter==="assigned"?"Records assigned to you by colleagues appear here.":"Changes made by you and your colleagues appear here."}</small></span></div>`;
    this.overlay(`<aside class="settings-drawer notification-drawer"><div class="modal-head"><div><div class="eyebrow">Activity across your workspaces</div><h2>Notifications</h2></div>${this.closeButton()}</div><div class="notification-tabs">${["all","mentions","assigned"].map(f=>`<button data-action="notification-filter" data-filter="${f}" class="${f===filter?"active":""}">${this.cap(f)}</button>`).join("")}<button data-action="mark-notifications">Mark all read</button></div><div class="notification-list" aria-busy="${loading}">${body}</div></aside>`,"drawer-overlay");
  }

  // Global search (Ctrl K / the search box in the top bar). Searches what this browser already holds for the signed-in
  // person — workspaces and boards they can see, column names, and the records of boards loaded in this session —
  // so nothing is downloaded just to search. Results are grouped, matches highlighted, with board/workspace context.
  // server: { q, status: "idle" | "loading" | "done" | "error", items, more, partial, message } — record results from
  // the server (all boards this person may see), merged with the ones found in this browser, without duplicates.
  showCommandPalette(model,query="",server=null) {
    const q=query.trim(), ql=q.toLowerCase(), has=(text)=>String(text??"").toLowerCase().includes(ql);
    const commandList=[["home","Go to Home","home"],["mywork","My work","work"],["new-board","Create board","board"],["new-record","Create record","plus"],["import","Import data","import"],["theme","Toggle light / dark theme","sun"],["settings","Settings","settings"],["notifications","Notifications","bell"],["shortcuts","Keyboard shortcuts","command"]];
    const spaces=model.workspaces.filter((w)=>!w.archived), groups=[];
    const item=(attrs,ic,title,context)=>`<button ${attrs}>${icon(ic)}<span><strong>${title}</strong>${context?`<small>${context}</small>`:""}</span></button>`;
    const boardItem=(b,w,titleHtml=null)=>item(`data-action="palette-board" data-id="${this.attr(b.id)}" data-workspace="${this.attr(w.id)}"`,"board",titleHtml??this.mark(b.name,q),this.escape(w.name));
    if(!q){
      groups.push(["Recent boards",model.recentBoardItems.map((b)=>item(`data-action="palette-board" data-id="${this.attr(b.id)}" data-workspace="${this.attr(b.workspaceId)}"`,"board",this.escape(b.name),this.escape(b.workspaceName))).join("")]);
      const recent=model.recentRecords.map((r)=>model.allRecords.find((a)=>a.id===r.id&&a.boardId===r.boardId)).filter(Boolean);
      groups.push(["Recent records",recent.map((r)=>item(`data-action="palette-record" data-id="${this.attr(r.id)}" data-board="${this.attr(r.boardId)}" data-workspace="${this.attr(r.workspaceId)}"`,"records",this.escape(r.serial),`${this.escape(r.boardName)} · ${this.escape(r.workspaceName||"")}`)).join("")]);
    } else {
      groups.push(["Workspaces",spaces.filter((w)=>has(w.name)).slice(0,6).map((w)=>item(`data-action="palette-workspace" data-id="${this.attr(w.id)}"`,"layout",this.mark(w.name,q),`${w.boards.filter((b)=>!b.archived).length} boards`)).join("")]);
      groups.push(["Boards",spaces.flatMap((w)=>w.boards.filter((b)=>!b.archived&&has(b.name)).map((b)=>boardItem(b,w))).slice(0,10).join("")]);
      groups.push(["Columns",spaces.flatMap((w)=>w.boards.filter((b)=>!b.archived).flatMap((b)=>(b.columns||[]).filter((c)=>has(c.label)).map((c)=>item(`data-action="palette-board" data-id="${this.attr(b.id)}" data-workspace="${this.attr(w.id)}"`,columnTypeIcons[c.type]||"text",this.mark(c.label,q),`Column · ${this.escape(b.name)} · ${this.escape(w.name)}`)))).slice(0,8).join("")]);
      // Records: the item name and every searchable cell (text, labels, numbers, dates, contact details, people).
      const recordHits=[];
      for(const w of spaces)for(const b of w.boards){
        if(b.archived)continue;
        const cols=(b.columns||[]).filter((c)=>c.type!=="files"&&c.type!=="checkbox");
        for(const r of b.records||[]){
          if(r.archived)continue;
          let hit=null;
          for(const c of cols){const v=r[c.key];const text=Array.isArray(v)?v.map((x)=>model.personName?model.personName(x):x).join(", "):v;if(text!==undefined&&text!==null&&text!==""&&has(text)){hit={c,text:String(text)};break;}}
          if(!hit)continue;
          const name=r.serial||r[cols[0]?.key]||"Record";
          const context=hit.c.key==="serial"?`${this.escape(b.name)} · ${this.escape(w.name)}`:`${this.escape(hit.c.label)}: ${this.mark(hit.text.length>80?hit.text.slice(0,80)+"…":hit.text,q)} · ${this.escape(b.name)} · ${this.escape(w.name)}`;
          recordHits.push(item(`data-action="palette-record" data-id="${this.attr(r.id)}" data-board="${this.attr(b.id)}" data-workspace="${this.attr(w.id)}"`,"records",hit.c.key==="serial"?this.mark(name,q):this.escape(name),context));
          if(recordHits.length>=20)break;
        }
        if(recordHits.length>=20)break;
      }
      // Server results: boards never opened here too. Names come from the boards this browser already lists.
      const shownIds=new Set([...recordHits.join("").matchAll(/data-action="palette-record" data-id="([^"]+)"/g)].map((m)=>m[1]));
      const where=new Map(spaces.flatMap((w)=>w.boards.map((b)=>[String(model.serverId?model.serverId(b.id):b.id),{w,b}])));
      const live=server&&server.q===q?server:null;
      if(live?.status==="done")for(const it of live.items){
        if(recordHits.length>=30)break;
        if(shownIds.has(it.recordId))continue;
        const place=where.get(it.boardId);if(!place||place.b.archived)continue;
        shownIds.add(it.recordId);
        const context=`${it.field?`${this.escape(it.field.label)}: ${this.mark(it.snippet||"",q)} · `:""}${this.escape(place.b.name)} · ${this.escape(place.w.name)}`;
        recordHits.push(item(`data-action="palette-record" data-id="${this.attr(it.recordId)}" data-board="${this.attr(place.b.id)}" data-workspace="${this.attr(place.w.id)}" data-title="${this.attr(it.title)}"`,"records",it.field?this.escape(it.title):this.mark(it.title,q),context));
      }
      const status=!live||!model.storage?.adapter?.searchRecords?"":live.status==="loading"?`<p class="search-status" role="status"><span class="loading-spinner" aria-hidden="true"></span> Searching all boards…</p>`:live.status==="error"?`<p class="search-status is-error" role="alert">${this.escape(live.message||"Couldn't search all boards.")} Showing matches from boards opened here. <button type="button" class="button secondary small" data-action="search-retry">Try again</button></p>`:live.more||live.partial?`<p class="search-status">More matches exist. Type more to narrow the search.</p>`:"";
      groups.push(["Records",recordHits.join("")+status]);
    }
    const commands=commandList.filter(([,t])=>!q||has(t)).sort((a,b)=>{const ai=model.recentCommands.indexOf(a[0]),bi=model.recentCommands.indexOf(b[0]);return (ai<0?99:ai)-(bi<0?99:bi);});
    groups.push(["Actions",commands.map(([c,t,ic])=>`<button data-action="run-command" data-command="${c}">${icon(ic)}<span>${q?this.mark(t,q):t}</span></button>`).join("")]);
    const shown=groups.filter(([,html])=>html);
    const content=shown.map(([name,html])=>`<section role="group" aria-label="${name}"><h3>${name}</h3>${html}</section>`).join("")||`<p class="quiet-empty search-empty">No matches for “${this.escape(q)}”. Try a board, column or record name.</p>`;
    const allBoards=Boolean(model.storage?.adapter?.searchRecords);
    const status=q?`${shown.reduce((n,[,html])=>n+(html.match(/<button /g)||[]).length,0)} results`:"";
    const root=document.querySelector("#overlay-root"), existing=root.querySelector(".command-modal");
    if(existing){existing.querySelector(".command-results").innerHTML=content;const s=existing.querySelector(".command-status");if(s)s.textContent=status;return;}
    this.overlay(`<div class="modal command-modal" role="dialog" aria-label="Search JARC"><div class="command-search">${icon("search")}<input data-action="command-search" aria-label="Search JARC" placeholder="Search workspaces, boards, columns and records…" autocomplete="off" autofocus aria-controls="command-results"><button class="icon-button" data-action="close-overlay" aria-label="Close search"><kbd>Esc</kbd></button></div><div class="command-results" id="command-results">${content}</div><div class="command-hint"><span><kbd>↑</kbd><kbd>↓</kbd> to move</span><span><kbd>Enter</kbd> to open</span><span class="command-status" role="status" aria-live="polite">${status}</span><span class="command-scope">${allBoards?"Searching all your boards":"Records: boards opened this session"}</span></div></div>`,"command-overlay");
  }
  showDescription(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="description-form"><div class="modal-head"><div><div class="eyebrow">Board context</div><h2>Board description</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Description<textarea name="description" rows="4" maxlength="240" placeholder="What is this board used for?">${this.escape(model.board.description)}</textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save description</button></div></form></div>`; }
  showImport(model) {
    this.overlay(`<div class="modal import-modal"><div class="modal-head"><div><div class="eyebrow">1 · Upload</div><h2>Import into ${this.escape(model.board.name)}</h2></div>${this.closeButton()}</div><p>Append records to this board. Your existing records stay in place.</p><button class="import-upload" data-action="choose-import-file">${icon("import")}<strong>Choose a CSV or JSON file</strong><small>For Excel, save your worksheet as CSV first.</small></button><form class="paste-import" data-action="paste-import-form"><label>Or paste CSV data<textarea name="text" rows="6" placeholder="Record / Serial,Owner,Status&#10;RR-001,M,New" required></textarea></label><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Preview and map columns</button></div></form></div>`);
  }

  refreshCommentIndicator(model,id){document.querySelectorAll(`[data-action="open-updates"][data-id="${CSS.escape(String(id))}"]`).forEach((b)=>{const row=model.rows.find((r)=>String(r.id)===String(id));if(row)b.outerHTML=this.commentButton(model,row);});}
  showRecordForm(model,row=null,{tab="fields"}={}) {
    const editing=Boolean(row); if(row)model.rememberRecord(row);
    const owners=[...new Set(["Unassigned",model.profile.initials,...model.members.map(m=>m.name),...model.rows.map(r=>r[model.ownerColumn?.key]).filter(Boolean)])];
    // Fields come only from this board's columns: add, rename or delete a column and the form follows.
    // Hidden columns stay out of New Record unless required with no default, so a record can always be saved.
    const columns=model.board.columns.filter(c=>editing||c.visible!==false||c.key==="serial"||(c.required&&!model.hasValue(c.defaultValue))), primaryColumn=columns.find(c=>c.key==="serial")||columns[0];
    const placeholders={text:"Add text",number:"0",email:"name@example.com",phone:"Phone number",link:"https://"};
    const fields=columns.map(c=>{
      const primary=c===primaryColumn, val=row?.[c.key]??c.defaultValue??"", required=c.required?"required":"", attrs=`data-column-key="${this.escape(c.key)}" data-column-type="${this.escape(c.type)}"`;
      const label=`${this.escape(c.label)}${c.required?' <span class="required-mark" aria-hidden="true">*</span>':""}${!model.columnShown(c)?' <small class="field-note">Hidden in this view</small>':""}`;
      // Files: the record's attachments (download here; add, preview or remove in the Files panel).
      if(c.type==="files"){if(!editing)return "";const list=model.attachmentsFor(row.id,c.key);return `<div class="full drawer-files" ${attrs}><span class="drawer-field-label">${label}</span><div class="drawer-file-list">${list.map((a)=>`<span class="drawer-file">${this.fileThumb(model,a)}<span class="file-meta"><strong>${this.escape(a.name)}</strong><small>${this.fileKind(a.type)} · ${this.fileSize(a.size)}${a.uploadedByName?` · ${this.escape(a.uploadedByName)}`:""}</small></span><a class="icon-button" data-action="download-file" data-name="${this.attr(a.name)}" href="${this.attr(model.attachmentUrl(a.id,{download:true}))}" download="${this.attr(a.name)}" aria-label="Download ${this.attr(a.name)}" title="Download">${icon("download")}</a></span>`).join("")||'<small class="field-note">No files yet.</small>'}</div><button type="button" class="button secondary small" data-action="drawer-files" data-id="${this.attr(row.id)}" data-field="${this.attr(c.key)}">${icon("paperclip")} ${list.length?"Manage files":"Add files"}</button></div>`;}
      let input, layout=primary?"full":"";
      if(model.isMultiColumn(c)){const chosen=model.valueList(val),pool=c.type==="owner"?this.cellOptions(model,c):model.effectiveOptions(c),choices=[...new Set([...chosen,...pool])];input=`<span class="choice-group" role="group" aria-label="${this.escape(c.label)}">${choices.map(o=>`<label class="choice-chip"><input type="checkbox" name="${this.attr(c.key)}" value="${this.escape(o)}" ${chosen.includes(o)?"checked":""}><span>${c.type==="owner"?this.escape(model.personLabel(o)):this.pill(o,model.optionColor(c,o))}</span></label>`).join("")||`<small class="field-note">${c.type==="owner"?"No one to assign yet.":"No labels yet."}</small>`}</span>`;layout="full";}
      else if(c.type==="owner")input=`<input name="${this.attr(c.key)}" list="record-owners" value="${this.escape(val||"Unassigned")}" ${required}>`;
      else if(["status","priority","group","dropdown"].includes(c.type)){const options=[...new Set([val,...model.effectiveOptions(c)].filter(Boolean))];input=`<select name="${this.attr(c.key)}" ${required}><option value="">Select…</option>${options.map(o=>`<option ${val===o?"selected":""}>${this.escape(o)}</option>`).join("")}</select>`;}
      else if(c.type==="checkbox")return `<label class="checkbox-field" ${attrs}><input type="checkbox" name="${this.attr(c.key)}" ${val?"checked":""}><span>${label}</span></label>`;
      else if(c.key==="notes"){input=`<textarea name="${this.attr(c.key)}" rows="4" placeholder="Add notes" ${required}>${this.escape(val)}</textarea>`;layout="full";}
      else input=`<input name="${this.attr(c.key)}" type="${({date:"date",number:"number",email:"email",phone:"tel",link:"url"})[c.type]||"text"}" value="${this.escape(val)}" placeholder="${primary?"Untitled":placeholders[c.type]||""}" ${required} ${primary?"autofocus":""}>`;
      return `<label class="${layout}" ${attrs}>${label}${input}</label>`;
    }).join("");
    const schemaHint=!editing&&columns.length===1?`<p class="record-form-hint">This board has one column. <button type="button" class="link-button" data-action="add-column">Add a column</button> to capture more details.</p>`:"";
    this.overlay(`<form class="record-drawer" data-action="record-form"><div class="modal-head"><div><div class="eyebrow">${this.escape(model.workspace?.name||"")}${model.workspace?" · ":""}${this.escape(model.board.name)}</div><h2 class="record-title">${editing?this.escape(row.serial||"Untitled record"):"New record"}</h2>${editing?(()=>{const list=model.visibleRows,i=list.findIndex((r)=>r.id===row.id);return `<p class="record-meta">${i>=0?`Record ${i+1} of ${list.length}`:""}${row.updatedAt?` · Updated ${this.relative(row.updatedAt)}`:""}${row.createdAt?` · Created ${this.time(row.createdAt)}`:""}</p>`;})():""}</div><div class="drawer-navigation">${editing?`<button class="icon-button" type="button" data-action="adjacent-record" data-id="${this.attr(row.id)}" data-direction="-1" aria-label="Previous record">${icon("left")}</button><button class="icon-button" type="button" data-action="adjacent-record" data-id="${this.attr(row.id)}" data-direction="1" aria-label="Next record">${icon("right")}</button>`:""}${this.closeButton()}</div></div><input type="hidden" name="id" value="${this.attr(row?.id||"")}">${editing?this.recordTabs(model,row):""}<div class="drawer-body"><div class="drawer-panel" data-panel="fields" id="drawer-panel-fields" role="${editing?"tabpanel":"group"}"><div class="record-form-grid">${fields}</div>${schemaHint}<datalist id="record-owners">${owners.map(o=>`<option value="${this.escape(o)}"></option>`).join("")}</datalist></div>${editing?`<div class="drawer-panel" data-panel="updates" id="drawer-panel-updates" role="tabpanel" hidden><div class="updates-panel" data-record="${this.attr(row.id)}"></div></div><div class="drawer-panel" data-panel="files" id="drawer-panel-files" role="tabpanel" hidden></div>`:""}${editing?`<div class="drawer-panel" data-panel="activity" id="drawer-panel-activity" role="tabpanel" hidden><section class="record-activity"><h3>Activity</h3>${(row.activity||[]).slice().reverse().slice(0,8).map(a=>`<div><span class="activity-dot"></span><span><strong>${this.escape(a.text)}</strong><small>${this.escape(a.by||"")} · ${this.relative(a.at)}</small></span></div>`).join("")||'<p>History is recorded from your next change.</p>'}${row.createdAt?`<small>Created ${this.time(row.createdAt)}</small>`:""}${row.updatedAt?`<small>Updated ${this.time(row.updatedAt)}</small>`:""}</section></div>`:""}</div><div class="modal-actions">${editing?`<button type="button" class="icon-button danger" data-action="delete" data-id="${this.attr(row.id)}" aria-label="Delete record">${icon("trash")}</button><button type="button" class="button secondary" data-action="archive-item" data-id="${this.attr(row.id)}">${row.archived?"Restore":"Archive"}</button>`:""}<span class="modal-spacer"></span><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">${editing?"Save changes":"Create record"}</button></div></form>`,"drawer-overlay");
    // What each field showed when the form opened: saving an existing record sends only fields changed here.
    const form=document.querySelector('#overlay-root form.record-drawer'); if(form)form.dataset.initial=JSON.stringify(this.formValues(form));
    if(editing){this.setupRecordTabs(model,row,tab);this.onRecordDrawer?.(row,tab);}
  }

  // The record form's current values, keyed by column (lists for multi-value fields).
  formValues(form){
    const out={};
    for(const field of form.querySelectorAll("[data-column-key]")){
      const key=field.dataset.columnKey, inputs=[...field.querySelectorAll(`[name="${CSS.escape(key)}"]`)];
      if(!inputs.length)continue;
      if(field.querySelector(".choice-group"))out[key]=inputs.filter(i=>i.checked).map(i=>i.value);
      else if(inputs[0].type==="checkbox")out[key]=inputs[0].checked;
      else out[key]=inputs[0].value;
    }
    return out;
  }
  // Puts a value into one record-form field (used when a colleague changes a field you haven't touched).
  setFormValue(form,key,value){
    const field=form.querySelector(`[data-column-key="${CSS.escape(key)}"]`); if(!field)return;
    const inputs=[...field.querySelectorAll(`[name="${CSS.escape(key)}"]`)];
    if(field.querySelector(".choice-group")){const list=Array.isArray(value)?value:[];inputs.forEach(i=>{i.checked=list.includes(i.value);});return;}
    if(inputs[0]?.type==="checkbox"){inputs[0].checked=Boolean(value);return;}
    if(inputs[0]?.tagName==="SELECT"&&value&&![...inputs[0].options].some(o=>o.value===value))inputs[0].add(new Option(value,value));
    if(inputs[0])inputs[0].value=value??"";
  }
  formNotice(form,html,kind="info"){let box=form.querySelector(".form-live-notice");if(!box){box=document.createElement("div");box.className="form-live-notice";box.setAttribute("role","status");form.querySelector(".drawer-body")?.prepend(box);}box.dataset.kind=kind;box.innerHTML=html;}

  // Skeleton rows while a board's records load (shape of the table, no flashing spinner).
  // Desktop: the records table fills the rest of the window and scrolls inside the board (its header stays visible).
  fitBoard(){const wrap=this.root?.querySelector?.(".board-view-region .table-wrap");if(!wrap)return;const top=Math.round(wrap.getBoundingClientRect().top+window.scrollY);if(top>0)document.documentElement.style.setProperty("--table-top",`${top}px`);}
  // ---- Motion (Phase 4). Animations only when what the person is looking at changes (another screen, board or view;
  // records finishing loading), never on routine re-renders such as live updates. Off with "reduce motion".
  reducedMotion(){return Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);}
  // Restarts a one-off animation class on an element.
  play(element,className){if(!element||this.reducedMotion())return;element.classList.remove(className);void element.offsetWidth;element.classList.add(className);element.addEventListener("animationend",()=>element.classList.remove(className),{once:true});}
  afterRender(model){
    if(typeof this.root?.querySelector!=="function")return; // rendered without a DOM (unit tests)
    this.fitBoard();
    const screenKey=[model.screen,model.workspace?.id||"",model.screen==="board"?model.board?.id||"":""].join("|");
    const viewKey=`${screenKey}|${model.currentView}|${model.showArchived?1:0}`;
    const region=this.root.querySelector(".board-view-region"), busy=Boolean(region?.querySelector('[aria-busy="true"]'));
    if(this.motionKeys&&screenKey!==this.motionKeys.screen)this.root.querySelectorAll(".workspace > :not(.topbar)").forEach((el)=>this.play(el,"view-enter"));
    else if(this.motionKeys&&viewKey!==this.motionKeys.view)this.play(region,"view-enter");
    else if(this.motionKeys?.busy&&!busy&&viewKey===this.motionKeys.view)this.play(region,"content-ready");
    this.motionKeys={screen:screenKey,view:viewKey,busy};
  }
  // Closing a menu, dialog or drawer: the page updates at once (nothing waits for an animation), while a copy of what
  // closed fades out on a separate, inert layer that the page's own code and selectors never see (a shadow root).
  exitLayer(){
    if(this.exitHost?.isConnected)return this.exitHost;
    if(typeof CSSStyleSheet!=="function"||!document.body.attachShadow)return null;
    try{
      const host=document.createElement("div");host.id="jarc-exit-layer";host.setAttribute("aria-hidden","true");host.inert=true;
      const shadow=host.attachShadow({mode:"open"}), sheet=new CSSStyleSheet();
      const rules=[...document.styleSheets].flatMap((s)=>{try{return [...s.cssRules].map((r)=>r.cssText);}catch{return [];}});
      sheet.replaceSync(`:host{position:fixed;inset:0;z-index:69;pointer-events:none;contain:strict}${rules.join("\n")}`);
      shadow.adoptedStyleSheets=[sheet];document.body.append(host);this.exitHost=host;return host;
    }catch{return null;}
  }
  exitGhost(root){
    if(!root?.children.length||this.reducedMotion())return;
    const host=this.exitLayer();if(!host)return;
    const layer=document.createElement("div");layer.className="exit-ghost";
    for(const child of root.children){const clone=child.cloneNode(true);clone.querySelectorAll("[id]").forEach((el)=>el.removeAttribute("id"));clone.classList.add("is-exiting");layer.append(clone);}
    host.shadowRoot.append(layer);
    setTimeout(()=>layer.remove(),260);
  }
  // Loading placeholders shaped like the view that is loading (they appear only if loading takes over ~150 ms).
  boardSkeleton(model){
    const view=model.currentView, line=(w,cls="")=>`<span class="skeleton skeleton-text ${cls}" style="width:${w}"></span>`;
    const wrap=(cls,inner,label="Loading records")=>`<section class="data-region skeleton-region ${cls}" aria-busy="true"><div role="status" aria-label="${label}">${inner}</div><span class="sr-only">${label}…</span></section>`;
    if(view==="kanban")return wrap("skeleton-kanban",Array.from({length:4},(_,c)=>`<div class="skeleton-lane">${line("46%")}${Array.from({length:3-(c%2)},(_,i)=>`<div class="skeleton-card">${line(["78%","64%","70%"][i])}${line("42%","is-small")}</div>`).join("")}</div>`).join(""));
    // The Calendar view is an agenda ("Records by date"): a header, then date cards.
    if(view==="calendar")return wrap("skeleton-calendar",`<div class="skeleton-calendar-head">${line("130px")}${line("70px","is-small")}</div><div class="skeleton-agenda">${Array.from({length:6},(_,i)=>`<div class="skeleton-list-card">${line("34%","is-small")}${line(["62%","48%","70%"][i%3])}</div>`).join("")}</div>`);
    if(view==="list")return wrap("skeleton-list",Array.from({length:6},(_,i)=>`<div class="skeleton-list-card">${line(["38%","52%","44%"][i%3])}${line(["62%","48%","70%"][i%3],"is-small")}</div>`).join(""));
    return this.skeletonRows(model);
  }
  feedSkeleton(count=5){return `<div class="feed-skeleton" aria-busy="true" role="status" aria-label="Loading activity">${Array.from({length:count},(_,i)=>`<div class="feed-skeleton-item"><span class="skeleton skeleton-avatar"></span><span class="feed-skeleton-lines"><span class="skeleton skeleton-text" style="width:${[72,58,80,64,50][i%5]}%"></span><span class="skeleton skeleton-text is-small" style="width:${[30,24,36][i%3]}%"></span></span></div>`).join("")}<span class="sr-only">Loading activity…</span></div>`;}
  // ---- Views (Phase 5). "+ Views": a new view (a column configuration of this board, as a table); optional layouts;
  // the board's views; archived records.
  showViewsMenu(model){
    const views=model.board.savedViews||[], icons=Object.fromEntries(VIEW_TYPES.map(([t,,i])=>[t,i])), current=model.activeView;
    document.querySelector("#overlay-root").innerHTML=`<div class="popover views-menu" role="menu" aria-label="Views"><button role="menuitem" class="views-menu-primary" data-action="new-view" data-type="table">${icon("plus")}<span><strong>New view</strong><small>Choose its columns, filters and sorting</small></span></button><button role="menuitem" data-action="duplicate-view" ${current?`data-id="${this.attr(current.id)}"`:""}>${icon("copy")} Duplicate ${current?`“${this.escape(current.name)}”`:"Main Table"}</button><div class="menu-section-label" role="presentation">Other layouts</div>${VIEW_TYPES.filter(([t])=>t!=="table").map(([type,label,ic])=>`<button role="menuitem" data-action="new-view" data-type="${type}">${icon(ic)} ${label} view</button>`).join("")}${views.length?`<div class="menu-section-label" role="presentation">This board's views</div>${views.map((v)=>`<button role="menuitem" data-action="open-view" data-id="${this.attr(v.id)}">${icon(icons[v.view]||"layout")} ${this.escape(v.name)}</button>`).join("")}`:""}<div class="menu-separator" role="separator"></div><button role="menuitem" data-action="archived-view">${icon("archive")} Archived records <small class="menu-count">${model.archivedCount}</small></button></div>`;
  }
  showNewView(model,type){
    const meta=VIEW_TYPES.find(([t])=>t===type)||VIEW_TYPES[0], base=type==="table"?"New view":`${meta[1]} view`;
    this.overlay(`<form class="modal small-modal" data-action="create-view-form"><div class="modal-head"><div><div class="eyebrow">${type==="table"?"New view":`New ${this.escape(meta[1].toLowerCase())} view`}</div><h2>Name this view</h2></div>${this.closeButton()}</div><input type="hidden" name="type" value="${this.attr(meta[0])}"><div class="form-grid"><label class="full">View name<input name="name" required maxlength="60" value="${this.attr(model.uniqueViewName(base))}" autofocus></label><p class="field-note full">It starts with Main Table's columns. Hide columns, filter and sort, then use “Save to this view”. Views show the same records for everyone on this board; nothing is copied or deleted.</p></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Create view</button></div></form>`);
  }
  showViewMenu(model,id){
    const v=model.board.savedViews.find((x)=>String(x.id)===String(id));if(!v)return;
    document.querySelector("#overlay-root").innerHTML=`<div class="popover view-menu" role="menu" aria-label="${this.attr(v.name)} view"><div class="popover-title"><strong>${this.escape(v.name)}</strong><small>${this.escape((VIEW_TYPES.find(([t])=>t===v.view)||VIEW_TYPES[0])[1])} layout</small></div>${model.viewChanged?`<button role="menuitem" data-action="save-active-view">${icon("work")} Save to this view</button>`:""}<button role="menuitem" data-action="rename-view" data-id="${this.attr(v.id)}">${icon("edit")} Rename</button><button role="menuitem" data-action="duplicate-view" data-id="${this.attr(v.id)}">${icon("copy")} Duplicate</button><div class="menu-separator" role="separator"></div><button role="menuitem" class="danger" data-action="request-delete-view" data-id="${this.attr(v.id)}">${icon("trash")} Delete view</button></div>`;
  }
  showRenameView(model,id){
    const v=model.board.savedViews.find((x)=>String(x.id)===String(id));if(!v)return;
    this.overlay(`<form class="modal small-modal" data-action="rename-view-form"><div class="modal-head"><div><div class="eyebrow">View</div><h2>Rename view</h2></div>${this.closeButton()}</div><input type="hidden" name="id" value="${this.attr(v.id)}"><div class="form-grid"><label class="full">View name<input name="name" required maxlength="60" value="${this.attr(v.name)}" autofocus></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save</button></div></form>`);
  }
  // Display columns (toolbar): search, All columns, a checkbox per column, how many are shown, and — in a view —
  // "Save to this view" when there are unsaved changes. Item is always shown. Hiding never deletes a column or data.
  columnPickerList(model,query=""){
    const q=query.trim().toLowerCase(), cols=model.orderedColumns.filter((c)=>!q||c.label.toLowerCase().includes(q));
    return cols.map((c)=>{const on=model.columnShown(c),primary=c.key==="serial";return `<label class="column-pick ${primary?"is-primary":""}"><input type="checkbox" data-action="column-toggle" data-key="${this.attr(c.key)}" ${on?"checked":""} ${primary?'disabled title="The Item column is always shown"':""}><span class="column-pick-icon">${icon(columnTypeIcons[c.type]||"text")}</span><span class="column-pick-label">${this.mark(c.label,q)}</span>${primary?'<small>Always shown</small>':""}</label>`;}).join("")||`<p class="popover-copy">No column matches “${this.escape(query)}”.</p>`;
  }
  columnPickerFooter(model){
    const total=model.board.columns.length, shown=model.board.columns.filter((c)=>model.columnShown(c)).length, view=model.activeView;
    return `<div class="column-picker-count" role="status" aria-live="polite">${shown} of ${total} columns shown</div>${view?(model.viewChanged?`<div class="column-picker-save"><span>Unsaved changes to “${this.escape(view.name)}”</span><button type="button" class="button primary small" data-action="save-active-view">Save to this view</button></div>`:`<p class="column-picker-note">Saved in “${this.escape(view.name)}”. Other views are not affected.</p>`):`<p class="column-picker-note">Main Table: changes are saved for everyone on this board.</p>`}`;
  }
  showColumnPicker(model,query=""){
    const total=model.board.columns.length, shown=model.board.columns.filter((c)=>model.columnShown(c)).length, all=shown===total;
    const existing=document.querySelector("#overlay-root .column-picker");
    if(existing){existing.querySelector(".column-pick-list").innerHTML=this.columnPickerList(model,query);existing.querySelector(".column-picker-footer").innerHTML=this.columnPickerFooter(model);const box=existing.querySelector('[data-action="column-toggle-all"]');box.checked=all;box.indeterminate=!all&&shown>1;return;}
    document.querySelector("#overlay-root").innerHTML=`<div class="popover column-picker" role="dialog" aria-label="Display columns"><div class="popover-title"><strong>Display columns</strong><small>${model.activeView?this.escape(model.activeView.name):"Main Table"}</small></div><label class="column-picker-search">${icon("search")}<input data-action="column-picker-search" placeholder="Search columns" aria-label="Search columns" autocomplete="off" autofocus></label><label class="column-pick column-pick-all"><input type="checkbox" data-action="column-toggle-all" ${all?"checked":""}><span class="column-pick-label">All columns</span></label><div class="column-pick-list">${this.columnPickerList(model,query)}</div><div class="column-picker-footer">${this.columnPickerFooter(model)}</div></div>`;
    const box=document.querySelector('#overlay-root [data-action="column-toggle-all"]');if(box)box.indeterminate=!all&&shown>1;
  }
  // Default column widths by type (until someone resizes a column): wide enough for typical content, never wider.
  colWidth(column){const own=this.model?.columnWidthFor?.(column)||column.width;if(own)return own;return column.key==="serial"?260:({checkbox:110,number:120,date:150,status:160,priority:150,dropdown:170,owner:170,files:170,email:220,phone:160,link:220,group:160,text:220})[column.type]||180;}
  // Global search: highlights each occurrence of the query in plain text (escaped).
  mark(text,q){const s=String(text??"");if(!q)return this.escape(s);const lower=s.toLowerCase(),needle=q.toLowerCase();let out="",at=0,i;while((i=lower.indexOf(needle,at))>=0){out+=this.escape(s.slice(at,i))+`<mark>${this.escape(s.slice(i,i+needle.length))}</mark>`;at=i+needle.length;}return out+this.escape(s.slice(at));}
  // ---- Phase 6: floating bulk-action bar (selected records), move targets, guarded bulk delete.
  showMoveTargets(model){
    const targets=model.moveTargets([...model.selected]);
    document.querySelector("#overlay-root").innerHTML=`<div class="popover move-targets" role="menu" aria-label="Move records to"><div class="popover-title"><strong>Move ${model.selected.size} record${model.selected.size===1?"":"s"} to</strong><small>Boards with matching columns</small></div>${targets.map((t)=>`<button role="menuitem" data-action="apply-bulk-move" data-board="${this.attr(t.board.id)}" ${t.reason?`disabled title="${this.attr(t.reason)}"`:""}>${icon("board")}<span><strong>${this.escape(t.board.name)}</strong><small>${this.escape(t.reason||t.workspace.name)}</small></span></button>`).join("")||'<p class="popover-copy">There are no other boards to move to.</p>'}</div>`;
  }
  showBulkDeleteConfirm(count,files){
    this.overlay(`<form class="modal small-modal" data-action="confirm-bulk-delete"><div class="modal-head"><div><div class="eyebrow">Permanent deletion</div><h2>Delete ${count} records?</h2></div>${this.closeButton()}</div><p>They are removed from this board for everyone.${files?` Their ${files} attached file${files===1?"":"s"} will be deleted permanently.`:""} Undo can restore the records${files?" but not the files":""} until you leave the board.</p><p class="field-note">To keep them instead, use <strong>Archive</strong>: archived records can be restored at any time.</p><label class="full">Type <strong>DELETE</strong> to confirm<input name="confirm" autocomplete="off" required autofocus></label><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button danger">Delete ${count} records</button></div></form>`);
  }
  skeletonRows(model,count=6){const cols=model.visibleColumns.length;return `<section class="data-region skeleton-region" aria-busy="true"><div class="group-title"><span class="skeleton skeleton-text" style="width:110px"></span></div><div class="table-wrap skeleton-table" role="status" aria-label="Loading records">${Array.from({length:count},(_,i)=>`<div class="skeleton-row">${Array.from({length:Math.min(cols,6)},(_,j)=>`<span class="skeleton skeleton-text" style="width:${[70,55,40,62,48,35][(i+j)%6]}%"></span>`).join("")}</div>`).join("")}</div><span class="sr-only">Loading records…</span></section>`;}
  showDensityMenu(model){document.querySelector("#overlay-root").innerHTML=`<div class="popover density-popover"><div class="popover-title"><strong>Table density</strong></div><button data-action="set-density" data-value="comfortable" class="${model.settings.density==="comfortable"?"selected":""}">Comfortable</button><button data-action="set-density" data-value="compact" class="${model.settings.density==="compact"?"selected":""}">Compact</button></div>`;}
  showViewOverflow(model){document.querySelector("#overlay-root").innerHTML=`<div class="popover view-overflow"><button data-action="manage-columns">${icon("columns")} Columns</button><button data-action="density-menu">${icon("list")} Density</button><button data-action="import">${icon("import")} Import records</button><button data-action="export" ${model.rows.length?"":"disabled"}>${icon("export")} Export records</button><button data-action="views-menu">${icon("layout")} Views</button><button data-action="archived-view">${icon("archive")} Archived records</button><button data-action="manage-groups">${icon("group")} Manage groups</button><button data-action="undo" ${model.canUndo?"":"disabled"}>Undo last change</button><button data-action="clear-filters">Reset view</button></div>`;}
  closeOverlay() { const root=document.querySelector("#overlay-root"); if(root) { this.exitGhost(root); root.innerHTML = ""; delete root.dataset.open; } }
  // action: true shows Undo (calls onUndo); {label, onClick} shows a custom action such as Retry.
  toast(message,action=false) {
    const toast=document.createElement("div");toast.className="toast";toast.setAttribute("role","status");toast.textContent=message;
    if(action){const button=document.createElement("button");button.type="button";button.textContent=action===true?"Undo":action.label;button.onclick=()=>{toast.remove();action===true?this.onUndo?.():action.onClick();};toast.append(button);}
    document.querySelector("#toast-region").append(toast);
    // Leaves with a short fade (immediately with reduced motion); an action button removes it at once.
    setTimeout(()=>{if(!toast.isConnected)return;if(this.reducedMotion())return toast.remove();toast.classList.add("is-leaving");setTimeout(()=>toast.remove(),180);},action?8000:3500);
    return toast;
  }
  // ---- Async UI helpers (Stage 8)
  renderLoading() {
    this.root.innerHTML=`<div class="app-skeleton" role="status" aria-live="polite" aria-busy="true"><aside class="sidebar skeleton-sidebar" aria-hidden="true"><div class="brand"><span class="brand-mark">J</span></div>${Array.from({length:5},(_,i)=>`<span class="skeleton skeleton-nav" style="width:${[70,55,62,48,58][i]}%"></span>`).join("")}</aside><main class="workspace"><header class="topbar" aria-hidden="true"><span class="skeleton skeleton-text" style="width:180px"></span></header><div class="home-content" aria-hidden="true"><span class="skeleton skeleton-title"></span><span class="skeleton skeleton-text" style="width:40%"></span><div class="skeleton-cards">${Array.from({length:4},()=>'<span class="skeleton skeleton-card"></span>').join("")}</div>${Array.from({length:4},()=>'<span class="skeleton skeleton-line"></span>').join("")}</div><p class="sr-only">Loading your workspace…</p></main></div>`;
  }
  // Busy state for a button running a pessimistic operation: disabled, spinner, same width, aria-busy.
  setBusy(button,busy) {
    if(!button)return;
    if(busy){button.dataset.previousMinWidth=button.style.minWidth;button.style.minWidth=button.offsetWidth+"px";button.disabled=true;button.setAttribute("aria-busy","true");button.classList.add("is-busy");}
    else{button.disabled=false;button.removeAttribute("aria-busy");button.classList.remove("is-busy");button.style.minWidth=button.dataset.previousMinWidth||"";delete button.dataset.previousMinWidth;}
  }
  // Shows an error inside the open dialog (falls back to a toast). The dialog stays open so the user can retry.
  showDialogError(message) {
    const panel=document.querySelector("#overlay-root .modal, #overlay-root .record-drawer, #overlay-root .settings-drawer, #overlay-root .popover");
    if(!panel){this.toast(message);return;}
    let box=panel.querySelector(".dialog-error");
    if(!box){box=document.createElement("p");box.className="dialog-error";box.setAttribute("role","alert");const actions=panel.querySelector(".modal-actions");actions?actions.before(box):panel.append(box);}
    box.textContent=message;
  }
  clearDialogError() { document.querySelector("#overlay-root .dialog-error")?.remove(); }

  date(value){if(!value)return "—";const key=String(value).slice(0,10);let text=DATE_CACHE.get(key);if(text===undefined){const d=new Date(key+"T00:00:00");text=Number.isNaN(d.getTime())?String(value):FORMATS.date.format(d);if(DATE_CACHE.size>2000)DATE_CACHE.clear();DATE_CACHE.set(key,text);}return text;}

  time(value) { return FORMATS.time.format(new Date(value)); }
  cap(value) { return value[0].toUpperCase()+value.slice(1); }
  // ---- Output helpers (Stage 5). Use the one that matches where the value lands:
  //   escape(v)    text content between tags
  //   attr(v)      a quoted attribute value (data-*, title, value, aria-*); null/undefined become ""
  //   safeHref(v)  a clickable URL: http, https, mailto and tel only; anything else returns "" (render as text)
  //   safeImage(v) an <img src>: only inline PNG/JPEG/WebP/GIF data URLs
  //   cssColor(v)  an inline colour: hex only, otherwise the fallback
  escape(value) { return String(value).replace(/[&<>'"]/g,(char)=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char])); }
  attr(value) { return this.escape(value ?? ""); }
  safeHref(value,type="link") {
    const text=String(value??"").trim(); if(!text||text.length>2048)return "";
    if(type==="email")return /^[^\s@<>"'()]+@[^\s@<>"'()]+\.[^\s@<>"'()]+$/.test(text)?"mailto:"+text:"";
    if(type==="phone")return /^\+?[0-9 ().-]{3,30}$/.test(text)?"tel:"+text.replace(/[^\d+]/g,""):"";
    let url; try{url=new URL(text);}catch{return "";}
    return ["http:","https:","mailto:","tel:"].includes(url.protocol)?url.href:"";
  }
  safeImage(value) { const text=String(value??""); return /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(text)?text:""; }
  cssColor(value,fallback="#64748b") { const text=String(value??"").trim(); return /^#[0-9a-f]{3,8}$/i.test(text)?text:fallback; }
  showImportPreview(model,rows,mapping=null) {
    const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))];
    const map=mapping||Object.fromEntries(model.board.columns.map(c=>[c.key,headers.find(h=>h.toLowerCase()===c.key.toLowerCase()||h.toLowerCase()===c.label.toLowerCase())||""]));
    const result=model.validateImport(rows,map);
    this.overlay(`<form class="modal import-modal" data-action="confirm-import-form"><div class="modal-head"><div><div class="eyebrow">2 · Preview & map / 3 · Validate</div><h2>Review your import</h2></div>${this.closeButton()}</div><p>${rows.length} rows found. ${result.valid.length} ready to import. ${result.issues.length} need review.</p><div class="import-mapping">${model.board.columns.map(c=>`<label>${this.escape(c.label)}${c.required?" *":""}<select name="${this.attr(c.key)}" data-action="import-mapping"><option value="">Use default / skip</option>${headers.map(h=>`<option value="${this.escape(h)}" ${map[c.key]===h?"selected":""}>${this.escape(h)}</option>`).join("")}</select></label>`).join("")}</div><div class="import-preview table-wrap"><table><thead><tr>${headers.map(h=>`<th>${this.escape(h)}</th>`).join("")}</tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr>${headers.map(h=>`<td>${this.escape(r[h]??"")}</td>`).join("")}</tr>`).join("")}</tbody></table></div><small>Previewing the first ${Math.min(rows.length,5)} rows.</small>${result.issues.length?`<details open class="import-issues"><summary>${result.issues.length} rows will be skipped — review issues</summary>${result.issues.slice(0,30).map(i=>`<p>Row ${i.row}: ${this.escape(i.reason)}</p>`).join("")}</details>`:""}<div class="modal-actions"><button type="button" class="button secondary" data-action="import">Back</button><button class="button primary" ${result.valid.length?"":"disabled"}>Import ${result.valid.length} records</button></div></form>`);
  }
  showSort(model) {
    this.overlay(`<form class="modal small-modal" data-action="sort-form"><div class="modal-head"><h2>Sort records</h2>${this.closeButton()}</div><div class="form-grid"><label class="full">Column<select name="key">${model.board.columns.map(c=>`<option value="${this.attr(c.key)}" ${(model.sortKey||model.sortColumn?.key)===c.key?"selected":""}>${this.escape(c.label)}</option>`).join("")}</select></label><label class="full">Direction<select name="direction"><option value="asc" ${model.sortDirection==="asc"?"selected":""}>Ascending</option><option value="desc" ${model.sortDirection==="desc"?"selected":""}>Descending</option></select></label></div><div class="modal-actions"><button class="button primary">Apply sort</button></div></form>`);
  }
  showShortcuts() {
    this.overlay(`<div class="modal small-modal"><div class="modal-head"><h2>Keyboard shortcuts</h2>${this.closeButton()}</div><div class="shortcut-list">${[["Search and commands","Ctrl / ⌘ K"],["Toggle sidebar","Ctrl / ⌘ B"],["Focus record search","/"],["Create a record","N"],["Edit the focused cell","Enter or start typing"],["Save a cell edit","Enter"],["Cancel a cell edit / close a panel","Esc"],["Next / previous cell","Tab / Shift Tab"],["Move between cells","Arrow keys"],["Reorder a focused row","Alt ↑ / ↓"],["Show this reference","?"]].map(([t,k])=>`<div><span>${t}</span><kbd>${k}</kbd></div>`).join("")}</div><p>Letter shortcuts are inactive while you type.</p></div>`);
  }
  overlay(html,className="") { document.querySelector("#overlay-root").innerHTML=`<div class="overlay ${className}" data-action="close-overlay">${html}</div>`; }
  closeButton(){return `<button type="button" class="icon-button" data-action="close-overlay" aria-label="Close">${icon("close")}</button>`;}
  relative(value){const seconds=Math.max(0,(Date.now()-new Date(value))/1000);if(!Number.isFinite(seconds))return "No recent activity";if(seconds<60)return "just now";if(seconds<3600)return Math.floor(seconds/60)+" min ago";if(seconds<86400)return Math.floor(seconds/3600)+" hr ago";if(seconds<604800)return Math.floor(seconds/86400)+" days ago";return this.time(value);}
  filterChips(model){return `<div class="filter-chips">${model.query?`<button data-action="remove-filter" data-key="query">Search: ${this.escape(model.query)} ${icon("close")}</button>`:""}${model.status!=="All"?`<button data-action="remove-filter" data-key="status">Status: ${this.escape(model.status)} ${icon("close")}</button>`:""}${model.quickFilter!=="all"?`<button data-action="remove-filter" data-key="quickFilter">${({mine:"My records",due:"Due soon",recent:"Recently updated"})[model.quickFilter]} ${icon("close")}</button>`:""}${model.columnFilter?`<button data-action="remove-filter" data-key="columnFilter">${this.escape(this.filterSummary(model))} ${icon("close")}</button>`:""}${model.query||model.status!=="All"||model.quickFilter!=="all"||model.columnFilter?'<button class="clear-chip" data-action="clear-filters">Clear all</button>':""}</div>`;}

}
window.AppView = AppView;
